/* Gerado por tools/gerar_i18n_conteudo.py */
window.DETALHES_I18N = {"en": {"semaglutida": {"oque": "Synthetic peptide similar to GLP-1, a hormone the gut releases after meals. It was modified to last for days in the body instead of minutes.", "age": ["Binds to the GLP-1 receptor in the pancreas, brain and stomach.", "In the pancreas, it stimulates insulin release only when glucose is high and reduces glucagon.", "In the brain (hypothalamus), it increases satiety and decreases hunger.", "In the stomach, it slows emptying, prolonging the feeling of fullness."], "hist": "Developed by Novo Nordisk from human GLP-1, with a fatty-acid side chain that binds to albumin and prolongs its action. Approved for type 2 diabetes in 2017 and for obesity in 2021 (FDA).", "estudos": "The SUSTAIN (diabetes) and STEP (obesity) programs showed lower blood glucose and meaningful weight loss; the SELECT trial showed a reduction in cardiovascular events in people with obesity and heart disease.", "evitar": "Personal or family history of medullary thyroid carcinoma or multiple endocrine neoplasia type 2, prior pancreatitis, pregnancy. Gastrointestinal effects are common; use requires a prescription and medical follow-up."}, "tirzepatida": {"oque": "A 39-amino-acid peptide that mimics two gut hormones at the same time: GIP and GLP-1 (dual agonist).", "age": ["Activates GLP-1 and GIP receptors, both involved in controlling glucose and appetite.", "Increases insulin in a glucose-dependent way and reduces appetite in the brain.", "The combination of both receptors appears to add to the effect on weight compared with GLP-1 alone."], "hist": "Developed by Eli Lilly. Approved by the FDA for type 2 diabetes in 2022 and for obesity in 2023.", "estudos": "The SURPASS (diabetes) and SURMOUNT (obesity) programs showed marked reductions in HbA1c and body weight, comparable or superior to those of the other therapies compared.", "evitar": "Same precautions as the class: history of medullary thyroid carcinoma, pancreatitis, pregnancy. Nausea and diarrhea are common. It may reduce the effectiveness of oral contraceptives at the start of treatment."}, "ocitocina": {"oque": "A natural 9-amino-acid hormone produced in the hypothalamus and released by the posterior pituitary. The pharmaceutical form is identical to the natural one.", "age": ["Binds to the oxytocin receptor in the uterus, increasing the frequency and strength of contractions.", "In the breasts, it triggers milk ejection during breastfeeding.", "In the brain, it takes part in social behaviors, but using this effect is still experimental."], "hist": "Isolated and synthesized by Vincent du Vigneaud in the 1950s, an achievement that earned him the 1955 Nobel Prize in Chemistry — it was the first peptide hormone ever synthesized.", "estudos": "Obstetric use (labor induction, control of postpartum hemorrhage) is well established. Studies on behavioral effects (trust, autism, anxiety) have produced inconsistent results.", "evitar": "Hospital use only. Risks include uterine hyperstimulation and fluid retention (water intoxication). It should not be used without obstetric supervision."}, "hormonio-do-crescimento-somatropina": {"oque": "Recombinant human growth hormone, a 191-amino-acid protein identical to the one produced by the pituitary gland.", "age": ["Binds to the GH receptor in many tissues, especially the liver.", "The liver responds by producing IGF-1, which promotes bone and muscle growth.", "It also acts on metabolism, favoring the use of fat as energy."], "hist": "Before 1985 it was extracted from the pituitary glands of cadavers, which caused cases of Creutzfeldt-Jakob disease. Since then it has been produced by recombinant DNA.", "estudos": "Effective in children with GH deficiency and in other approved indications (Turner syndrome, chronic kidney disease, etc.). In healthy adults there is no proven benefit and there are risks.", "evitar": "Active cancer, proliferative diabetic retinopathy and use by healthy people for cosmetic or athletic purposes (banned by WADA). Effects: fluid retention, insulin resistance."}, "liraglutida": {"oque": "A GLP-1 analog about 97% similar to the human hormone, with a longer action than the natural one.", "age": ["Activates the GLP-1 receptor, stimulating insulin when glucose is high.", "Reduces appetite by acting on the hypothalamus.", "Slows gastric emptying."], "hist": "From Novo Nordisk; approved for type 2 diabetes in 2010 (Victoza) and for obesity in 2014 (Saxenda). It was one of the forerunners of semaglutide.", "estudos": "The LEADER trial showed a reduction in cardiovascular events in type 2 diabetes; the SCALE trials showed moderate weight loss.", "evitar": "History of medullary thyroid carcinoma or MEN2, pancreatitis, pregnancy. Nausea is frequent at the start."}, "insulina": {"oque": "The glucose hormone, made of two chains (A with 21 and B with 30 amino acids) joined by disulfide bridges.", "age": ["Binds to the insulin receptor on muscle, liver and fat cells.", "Promotes glucose entry into cells and glycogen synthesis.", "Reduces glucose production by the liver, lowering blood glucose."], "hist": "Discovered in 1921 by Banting and Best; it was the first peptide used as a medicine. Today it is produced by recombinant DNA, with rapid- and long-acting analogs.", "estudos": "Studies such as the DCCT showed that intensive glucose control reduces the complications of type 1 diabetes.", "evitar": "The main risk is hypoglycemia (low blood glucose), which can be severe. Use only with a prescription and guidance for dose adjustment."}, "teriparatida": {"oque": "Active fragment (amino acids 1–34) of human parathyroid hormone, used to treat osteoporosis.", "age": ["Given in intermittent peaks, it activates osteoblasts (bone-forming cells).", "This increases bone mass and resistance to fractures.", "Unlike continuous exposure, which favors bone loss."], "hist": "Approved by the FDA in 2002 as the first anabolic (bone-forming) treatment for osteoporosis.", "estudos": "Trials showed a reduction in vertebral and non-vertebral fractures in postmenopausal women.", "evitar": "Paget's disease, prior skeletal radiation therapy, bone cancer or metastases, hypercalcemia. The total duration of use is limited."}, "tesamorelina": {"oque": "Synthetic analog of GHRH (growth hormone-releasing hormone), with 44 amino acids.", "age": ["Stimulates the pituitary to release the body's own GH.", "GH increases IGF-1, which helps reduce visceral fat.", "Preserves the natural rhythm of GH release."], "hist": "Approved by the FDA in 2010 (Egrifta) to reduce excess abdominal fat in people with HIV and lipodystrophy.", "estudos": "Two phase 3 trials showed a reduction in visceral fat in people living with HIV; the benefit disappears when use is stopped.", "evitar": "Active cancer, pregnancy and pituitary dysfunction. It may worsen glucose tolerance."}, "retatrutida": {"oque": "Investigational peptide that activates three receptors at once: GLP-1, GIP and glucagon (triple agonist).", "age": ["The GLP-1 and GIP components reduce appetite and improve blood glucose.", "The glucagon receptor may increase energy expenditure and reduce liver fat."], "hist": "Developed by Eli Lilly and still in phase 3 (TRIUMPH program); it is not approved.", "estudos": "Phase 2 results, published in a high-impact journal, showed very marked weight loss; phase 3 data are still being completed.", "evitar": "Not approved: use outside clinical trials has no established safety. Gastrointestinal effects were frequent in the studies."}, "cagrilintida": {"oque": "Long-acting analog of amylin, a hormone co-secreted with insulin that helps control satiety.", "age": ["Activates amylin and calcitonin receptors in the brain.", "Increases satiety and slows gastric emptying.", "It is usually studied in combination with semaglutide (CagriSema)."], "hist": "From Novo Nordisk, in phase 3 for obesity (REDEFINE program).", "estudos": "Phase 2 studies showed weight loss, with a greater effect when combined with semaglutide.", "evitar": "Not yet approved. Nausea was the most common adverse effect."}, "survodutida": {"oque": "Dual agonist of the glucagon and GLP-1 receptors, studied for obesity and fatty liver disease (MASH).", "age": ["The GLP-1 component reduces appetite.", "Glucagon increases energy expenditure and fat burning in the liver."], "hist": "Developed by Boehringer Ingelheim; in phase 3 (SYNCHRONIZE program).", "estudos": "Phase 2 showed weight loss and a reduction in liver fat.", "evitar": "Not approved. Nausea and vomiting were frequent."}, "mazdutida": {"oque": "Dual GLP-1 and glucagon agonist developed in China for obesity and type 2 diabetes.", "age": ["Reduces appetite via GLP-1.", "Increases energy expenditure via glucagon."], "hist": "Developed by Innovent in partnership with Lilly; in phase 3 in China.", "estudos": "Phase 2 and early phase 3 studies showed weight loss and metabolic improvement.", "evitar": "Not approved by the major agencies. Gastrointestinal effects are expected."}, "pramlintida": {"oque": "Synthetic analog of amylin, used together with mealtime insulin.", "age": ["Slows stomach emptying.", "Reduces glucagon release after meals.", "Increases satiety."], "hist": "Approved by the FDA in 2005 (Symlin) for type 1 and type 2 diabetes in people using insulin.", "estudos": "It showed a modest drop in HbA1c and slight weight loss.", "evitar": "Carries a warning about severe hypoglycemia when combined with insulin; contraindicated in gastroparesis."}, "setmelanotida": {"oque": "Agonist of the MC4R receptor, which regulates hunger and energy expenditure, for rare genetic forms of obesity.", "age": ["Activates the MC4R receptor in the hypothalamus, in a pathway that normally signals satiety.", "In the genetic variants in which this pathway is defective, it restores part of the signal."], "hist": "Approved by the FDA in 2020 (Imcivree) for obesity due to POMC, PCSK1 or LEPR deficiency, and later for Bardet-Biedl syndrome.", "estudos": "In people with these rare deficiencies there was meaningful weight loss and reduced hunger.", "evitar": "Skin darkening and injection-site reactions are common; use is restricted to specific genetic indications."}, "dasiglucagona": {"oque": "Stable, ready-to-use glucagon analog for treating severe hypoglycemia.", "age": ["Activates the glucagon receptor in the liver.", "The liver releases stored glucose, raising blood glucose."], "hist": "Approved by the FDA in 2021 (Zegalogue) for severe hypoglycemia in people with diabetes.", "estudos": "Trials showed blood glucose recovery within a few minutes, comparable to traditional glucagon.", "evitar": "Caution in pheochromocytoma and insulinoma. Nausea and vomiting are common."}, "gonadorelina-gnrh": {"oque": "Gonadotropin-releasing hormone, with 10 amino acids, which directs the pituitary's control of reproductive hormones.", "age": ["Stimulates the pituitary to release FSH and LH.", "The pulsatile pattern is essential: pulses maintain function, while continuous exposure blocks it."], "hist": "Its structure was discovered by Schally and Guillemin (1977 Nobel Prize).", "estudos": "Used in diagnosis and in specific fertility protocols; its analogs are far more widely used.", "evitar": "Use only in a specialized medical setting."}, "leuprorrelina": {"oque": "GnRH analog that, when used continuously, stops stimulating and instead suppresses sex hormones.", "age": ["Initially causes a brief rise in LH and FSH.", "With continuous exposure, the receptors become desensitized and testosterone or estrogen production falls."], "hist": "In use since the 1980s, it is a cornerstone of hormonal treatment for advanced prostate cancer.", "estudos": "Well established in prostate cancer, endometriosis, uterine fibroids and precocious puberty.", "evitar": "Pregnancy. Effects of the hormonal drop: hot flashes, bone loss, mood changes."}, "octreotida": {"oque": "Synthetic 8-amino-acid analog of somatostatin, much longer-lasting than the natural hormone.", "age": ["Binds to somatostatin receptors and inhibits the release of GH, insulin, glucagon and other hormones.", "Reduces secretion in the digestive tract."], "hist": "Approved in the 1980s; used in acromegaly and neuroendocrine tumors.", "estudos": "Lowers GH/IGF-1 in acromegaly and controls symptoms of carcinoid tumors.", "evitar": "May cause gallstones and alter blood glucose; requires medical follow-up."}, "abaloparatida": {"oque": "Analog of parathyroid hormone-related peptide (PTHrP), a bone-forming agent.", "age": ["Activates the PTH1 receptor in a way that favors bone formation.", "Increases bone mineral density."], "hist": "Approved by the FDA in 2017 (Tymlos) for postmenopausal osteoporosis.", "estudos": "The ACTIVE trial showed a reduction in vertebral and non-vertebral fractures.", "evitar": "Dizziness and a fast heart rate on standing may occur; caution with hypercalcemia."}, "vosoritida": {"oque": "Analog of C-type natriuretic peptide (CNP), for children with achondroplasia.", "age": ["Activates the NPR-B receptor in the growth plates.", "Counteracts part of the excess FGFR3 signaling that slows bone growth."], "hist": "Approved by the FDA in 2021 (Voxzogo) as the first medicine specifically for achondroplasia.", "estudos": "A modest but sustained increase in annual growth velocity in children.", "evitar": "May lower blood pressure; use restricted to specialized pediatric care."}, "timosina-alfa-1": {"aviso": "Regional approval: this item is not approved by the FDA or by Anvisa. The “Approved” label refers to its use in some countries. Check directly with the regulatory agency in your country.", "oque": "A 28-amino-acid peptide originally isolated from the thymus, a gland of the immune system.", "age": ["Modulates immune cells, such as T lymphocytes and dendritic cells.", "Appears to enhance the immune response to viruses and vaccines."], "hist": "Used in some countries, such as China and Italy, for hepatitis B/C and as an adjuvant; it is not FDA-approved for this purpose.", "estudos": "Results are mixed, with studies of variable size and quality.", "evitar": "Caution in people taking immunosuppressants or with a transplant. Always check its status with the regulatory agency in your country."}, "larazotida": {"oque": "An 8-amino-acid peptide that acts on the junctions between intestinal cells, studied in celiac disease.", "age": ["Regulates the tight junctions of the intestinal epithelium.", "Aims to reduce the passage of gluten and other molecules into the intestinal wall."], "hist": "In development for years; it had mixed results in phase 3.", "estudos": "Some studies showed fewer symptoms in people with celiac disease on a gluten-free diet, but it is not approved.", "evitar": "It does not replace a gluten-free diet. Still under investigation."}, "teduglutida": {"oque": "GLP-2 analog used in short bowel syndrome.", "age": ["Activates GLP-2 receptors in the intestine.", "Stimulates mucosal growth and increases the absorption of fluids and nutrients."], "hist": "Approved by the FDA in 2012 (Gattex).", "estudos": "It reduced the need for parenteral nutrition in patients with short bowel syndrome.", "evitar": "Polyps and gastrointestinal cancer require prior evaluation and colonoscopic surveillance."}, "apraglutida": {"oque": "Long-acting GLP-2 analog studied in short bowel syndrome.", "age": ["Activates GLP-2 receptors, promoting the growth and function of the intestinal mucosa."], "hist": "Developed for once-weekly administration; in phase 3.", "estudos": "Phase 2 studies showed a reduced need for parenteral support.", "evitar": "Not approved. Safety profile still under evaluation."}, "zilucoplana": {"oque": "Macrocyclic peptide that blocks the C5 component of the complement system.", "age": ["Binds to C5 and prevents its cleavage.", "Reduces complement-mediated damage at the neuromuscular junction in myasthenia gravis."], "hist": "Approved in 2023 (Zilbrysq) for generalized myasthenia gravis with anti-AChR antibodies.", "estudos": "The RAISE trial showed improvement on activities-of-daily-living scales.", "evitar": "Increased risk of meningococcal infections; requires prior vaccination and monitoring."}, "pegcetacoplana": {"oque": "Cyclic peptide linked to polyethylene glycol that inhibits complement component C3.", "age": ["Binds to C3 and blocks complement activation.", "Prevents the destruction of blood cells in paroxysmal nocturnal hemoglobinuria (PNH)."], "hist": "Approved in 2021 (Empaveli) for PNH, and later as an intravitreal formulation for geographic atrophy (Syfovre).", "estudos": "It outperformed the comparator therapy in PNH; in geographic atrophy it reduced the rate of lesion growth.", "evitar": "Risk of serious infections by encapsulated bacteria; vaccinations are mandatory."}, "elamipretida-ss-31": {"oque": "Tetrapeptide that concentrates in the inner mitochondrial membrane.", "age": ["Binds to cardiolipin, a mitochondrial lipid.", "Helps stabilize the membrane and improve the efficiency of energy production."], "hist": "Studied for years in mitochondrial diseases; it received FDA accelerated approval for Barth syndrome.", "estudos": "Results on muscle strength and function depended on the outcome measured; approval was based on markers.", "evitar": "Injection-site reactions are common. Use only for a specific indication."}, "semax": {"aviso": "Semax is not approved by the FDA or by Anvisa. The clinical use described is regional (Russia) and independent evidence is limited. Check directly with regulatory agencies.", "oque": "Synthetic peptide derived from ACTH (fragment 4–10) with the addition of Pro-Gly-Pro, developed in Russia.", "age": ["Modulates neurotrophic factors such as BDNF.", "May influence neurotransmitters and the stress response."], "hist": "Used clinically in Russia for stroke and other conditions; it is not approved by the FDA.", "estudos": "Most studies are Russian, with few independent trials and heterogeneous designs.", "evitar": "Limited international evidence. Check the regulatory status directly with the agency in your country."}, "bremelanotida-pt-141": {"oque": "Melanocortin analog that acts on the central nervous system, approved for low sexual desire in premenopausal women.", "age": ["Activates melanocortin receptors in the brain.", "Modulates sexual desire pathways, not blood flow like erectile dysfunction drugs."], "hist": "Approved by the FDA in 2019 (Vyleesi).", "estudos": "The RECONNECT studies showed a modest improvement in desire compared with placebo.", "evitar": "May temporarily raise blood pressure; avoid in uncontrolled hypertension or cardiovascular disease. Nausea is common."}, "nisina": {"oque": "Antimicrobial peptide (lantibiotic) produced by milk bacteria, used as a food preservative.", "age": ["Binds to lipid II in the cell wall of Gram-positive bacteria.", "Forms pores in the membrane and blocks cell wall construction."], "hist": "Used in food preservation for decades; recognized as safe (GRAS) for this use.", "estudos": "There are many studies in foods; clinical applications are still under research.", "evitar": "Its use as a preservative is regulated; it is not an approved medicine for treating infections."}, "glutationa": {"aviso": "Debated evidence: oral absorption is considered low, but some studies report different results. Infusions and cosmetic uses lack solid support. Seek medical advice.", "oque": "Tripeptide made of glutamate, cysteine and glycine; the main antioxidant produced inside cells.", "age": ["Neutralizes free radicals and peroxides.", "Takes part in drug detoxification in the liver.", "Keeps other antioxidants, such as vitamin C, in their active form."], "hist": "Discovered in 1921; today it is a topic of supplementation and of clinical use in specific settings (such as the antidote N-acetylcysteine, which supplies cysteine).", "estudos": "Oral absorption is low, and results of supplements and infusions for skin lightening or detoxification lack solid evidence.", "evitar": "Infusions outside medical indication do not have well-established safety. Asthma may worsen with the inhaled form."}, "testosterona": {"oque": "Steroid hormone (not a peptide) produced mainly in the testes and, in smaller amounts, in the ovaries and adrenal glands.", "age": ["Crosses the cell membrane and binds to the androgen receptor.", "In some tissues it is converted into dihydrotestosterone (more potent) or into estradiol.", "These signals maintain muscle mass, bone, libido, mood and red blood cell production."], "hist": "Isolated in 1935 and synthesized the same year; it is one of the foundations of modern endocrinology. Gels, long-acting ester injections and patches are available.", "estudos": "In men with confirmed hypogonadism, it improves libido, mild mood symptoms, lean mass and bone density. The TRAVERSE trial showed no increase in major cardiovascular events in at-risk men, but reported more atrial fibrillation and other events.", "evitar": "Prostate or breast cancer, polycythemia, untreated severe sleep apnea, wish to have children (it suppresses fertility). Cosmetic or sports use is prohibited by WADA and is not an approved indication."}, "estradiol": {"oque": "The main estrogen, a steroid hormone produced mostly in the ovaries before menopause.", "age": ["Binds to estrogen receptors alpha and beta in the uterus, breast, bone, blood vessels and brain.", "Regulates the menstrual cycle, maintains the vaginal lining and slows bone loss.", "Acts on the brain's temperature center, which explains its effect on hot flashes."], "hist": "Isolated in 1930. Menopausal hormone therapy underwent a major review after the WHI study (2002), which changed recommendations on age and duration.", "estudos": "Reduces hot flashes and bone loss. The risk of thrombosis and breast cancer depends on the route (oral versus skin), combination with a progestogen, age at initiation and duration of use.", "evitar": "Hormone-dependent breast or endometrial cancer, prior thrombosis, undiagnosed genital bleeding, severe liver disease, smoking combined with the oral route at older ages."}, "progesterona": {"oque": "Steroid hormone produced mainly after ovulation and, during pregnancy, by the placenta.", "age": ["Binds to progesterone receptors in the uterus, breast and brain.", "Transforms the endometrium, preparing it for implantation, and maintains pregnancy.", "Protects the endometrium from excess estrogen in menopausal therapy."], "hist": "Isolated in 1934. The micronized form, identical to the natural hormone, enabled oral and vaginal use.", "estudos": "Reduces the risk of endometrial hyperplasia with estrogen. In women with a short cervix, vaginal progesterone reduces preterm birth; for recurrent miscarriage the benefit is limited to subgroups.", "evitar": "Undiagnosed genital bleeding, breast cancer, active thrombosis, severe liver disease. It may cause drowsiness, so it is usually taken at night."}, "hidrocortisona-cortisol": {"oque": "Pharmaceutical form of cortisol, the main glucocorticoid produced by the adrenal glands.", "age": ["Binds to the glucocorticoid receptor, which changes the expression of many genes.", "Raises glucose, mobilizes fat and protein, and maintains blood pressure.", "Reduces the production of inflammatory signals and suppresses the immune response."], "hist": "Cortisone was first used in arthritis in 1948 and earned the 1950 Nobel Prize for Kendall, Hench and Reichstein.", "estudos": "It is the basis of replacement therapy in Addison's disease and congenital adrenal hyperplasia. As an anti-inflammatory it has proven efficacy, but risk increases with dose and duration.", "evitar": "Long-term use requires monitoring of glucose, blood pressure, bone and infections. Withdrawal must be gradual to avoid adrenal crisis. Stopping without guidance is dangerous."}, "dhea-prasterona": {"oque": "Steroid hormone produced in the adrenal glands, a precursor of testosterone and estradiol; its levels fall with age.", "age": ["It is converted in tissues into androgens and estrogens according to local needs.", "The vaginal form acts locally on the mucosa, with little absorption into the bloodstream."], "hist": "Popularized as the “youth hormone” in the 1990s; the vaginal form was approved by the FDA in 2016 (Intrarosa).", "estudos": "The vaginal form improves postmenopausal dyspareunia. For oral use in healthy people, studies show no consistent benefit and there are safety concerns.", "evitar": "Hormone-dependent cancers, undiagnosed vaginal bleeding, pregnancy. Prohibited in sports competition by WADA."}, "levotiroxina-t4": {"oque": "Synthetic form of T4, the main hormone produced by the thyroid.", "age": ["It is converted into T3 in tissues, which binds to receptors in the cell nucleus.", "Increases energy expenditure, heart rate and heat production."], "hist": "Thyroxine was isolated in 1914 and synthesized in 1927. It is one of the most prescribed medicines in the world.", "estudos": "Normalizes TSH and improves hypothyroidism symptoms. In mild subclinical hypothyroidism in older adults, trials showed no clear benefit.", "evitar": "Take on an empty stomach and separate from calcium, iron and antacids. Excess causes palpitations, bone loss and arrhythmia. It is not for weight loss."}, "liotironina-t3": {"oque": "Active form of thyroid hormone, with rapid and short action.", "age": ["Binds directly to nuclear thyroid hormone receptors.", "Takes effect within a few hours, but requires divided doses to avoid peaks."], "hist": "Used since the 1950s in situations where a rapid or reversible effect is desired.", "estudos": "The T4 + T3 combination showed no consistent advantage in most trials; it may be considered in selected cases by a specialist.", "evitar": "People with heart disease and older adults need caution. Use for weight loss is dangerous and not approved."}, "melatonina": {"oque": "Hormone produced at night by the pineal gland that helps regulate the sleep–wake rhythm.", "age": ["Binds to MT1 and MT2 receptors, mainly in the suprachiasmatic nucleus of the hypothalamus.", "Signals darkness and advances or delays the biological clock depending on when it is taken."], "hist": "Discovered in 1958. In the US it is sold as a supplement, while in Europe there is a prolonged-release medicine (Circadin).", "estudos": "Slightly reduces the time to fall asleep and helps in delayed sleep phase and jet lag. The effect in common insomnia is modest.", "evitar": "Caution with anticoagulants and sedatives. Supplement labels may differ from actual content; children only with medical guidance."}, "gonadotrofina-corionica-hcg": {"oque": "Hormone produced by the placenta during pregnancy; it is a glycoprotein, not a short peptide, and acts like LH.", "age": ["Binds to the LH/hCG receptor on Leydig cells in the testes and in the ovaries.", "Stimulates testosterone production or ovulation, depending on the context."], "hist": "It was identified in the urine of pregnant women in the 1920s, the basis of the first pregnancy tests.", "estudos": "Effective for inducing ovulation and in secondary hypogonadism. Trials showed it does not help with weight loss.", "evitar": "Hormone-sensitive cancers, pregnancy (outside fertility protocols). Prohibited by WADA in men."}, "glucagon": {"oque": "29-amino-acid peptide hormone produced by the alpha cells of the pancreas.", "age": ["Binds to the glucagon receptor in the liver.", "Stimulates glycogen breakdown and glucose production, raising blood glucose within minutes."], "hist": "Discovered in 1923. Ready-to-use and nasal forms now exist, making rescue by lay people easier.", "estudos": "Reverses severe hypoglycemia with efficacy demonstrated in trials; the effect depends on the presence of glycogen in the liver.", "evitar": "Less effective in prolonged fasting, alcoholism and adrenal insufficiency. May cause nausea and vomiting; turn the patient onto their side."}, "calcitonina": {"oque": "32-amino-acid hormone produced by the C cells of the thyroid.", "age": ["Binds to the calcitonin receptor on osteoclasts.", "Reduces bone resorption and the release of calcium into the blood."], "hist": "Discovered in 1962. Salmon calcitonin is more potent than the human form.", "estudos": "Useful in acute hypercalcemia and Paget's disease. In osteoporosis, the fracture benefit is small and there is a warning about a possible increase in cancer with prolonged use.", "evitar": "Hypocalcemia and allergy to fish proteins. The nasal form has been withdrawn in some markets."}, "desmopressina": {"oque": "Synthetic analog of vasopressin, with 9 amino acids and less effect on blood pressure.", "age": ["Binds to the V2 receptor in the collecting ducts of the kidneys.", "Increases water reabsorption and reduces urine volume.", "Also raises factor VIII and von Willebrand factor, aiding coagulation."], "hist": "Developed in the 1960s and used since then for diabetes insipidus and enuresis.", "estudos": "Reduces wet nights in children and the number of nighttime awakenings in adults with nocturia.", "evitar": "Risk of severe hyponatremia, especially in older adults and with excess fluid intake. Avoid with certain diuretics and anti-inflammatory drugs."}, "metreleptina": {"oque": "Analog of leptin, a protein produced by adipose tissue that informs the brain about energy reserves.", "age": ["Binds to the leptin receptor in the hypothalamus and other tissues.", "In people with lipodystrophy and very low leptin, it reduces hunger and improves insulin sensitivity and liver fat."], "hist": "Approved by the FDA in 2014 (Myalept) under a restricted safety program.", "estudos": "Reduces HbA1c and triglycerides in patients with generalized lipodystrophy. It is not effective in common obesity, in which leptin is usually high.", "evitar": "Boxed warning for neutralizing antibodies and T-cell lymphoma. May require a reduction in insulin dose."}, "vitamina-d3-colecalciferol": {"oque": "Fat-soluble vitamin that the skin produces with sunlight and that also comes from the diet; it works like a hormone.", "age": ["In the liver it becomes 25-hydroxyvitamin D and, in the kidneys, calcitriol (the active form).", "Calcitriol binds to the vitamin D receptor and increases calcium absorption in the intestine.", "It also plays a role in muscle cells and the immune system."], "hist": "Its link to rickets was clarified in the 1920s. Fortification of milk and foods reduced rickets.", "estudos": "Prevents rickets and osteomalacia. In large trials (VITAL, D2d), supplementation in people without deficiency did not significantly prevent cancer, heart disease or diabetes.", "evitar": "Avoid very high doses without testing: hypercalcemia, stones and kidney injury. People with sarcoidosis or hyperparathyroidism need monitoring."}, "vitamina-b12-cobalamina": {"oque": "Water-soluble vitamin that contains cobalt; it is produced only by microorganisms and comes from animal-source foods.", "age": ["To be absorbed it needs intrinsic factor, produced in the stomach.", "It acts in two enzymes: one in methionine synthesis (with folate) and another in fatty acid metabolism.", "Without it, megaloblastic anemia and nerve damage occur."], "hist": "Pernicious anemia was fatal until the discovery of liver therapy, which earned the 1934 Nobel Prize.", "estudos": "Replacement treats anemia and neuropathy. In people without deficiency, supplementation did not consistently improve energy or memory.", "evitar": "Metformin, proton pump inhibitors, bariatric surgery and a vegan diet increase the risk of deficiency. High oral doses work even without intrinsic factor."}, "vitamina-c-acido-ascorbico": {"oque": "Water-soluble vitamin that humans cannot produce and must obtain from fruits and vegetables.", "age": ["It is a cofactor for enzymes that form collagen.", "Neutralizes free radicals and regenerates vitamin E.", "Increases the absorption of plant-source iron."], "hist": "Sailors' scurvy was treated with citrus fruits by James Lind in 1747, in one of the first clinical trials.", "estudos": "Prevents scurvy. For colds, it slightly reduces duration in regular users, without preventing the illness in most people.", "evitar": "High doses favor oxalate stones and diarrhea, interfere with glucose meters and increase iron absorption in people with hemochromatosis."}, "vitamina-b6-piridoxina": {"oque": "Water-soluble vitamin that gives rise to pyridoxal phosphate, a cofactor for more than a hundred enzymes.", "age": ["Takes part in amino acid conversion and in the synthesis of neurotransmitters such as serotonin and GABA.", "It is also required to form hemoglobin."], "hist": "Identified in the 1930s; deficiency is rare and usually linked to medicines or alcoholism.", "estudos": "May relieve nausea in pregnancy, with or without doxylamine. Evidence for PMS and depression is weak.", "evitar": "High, prolonged doses (above ~100 mg/day) cause peripheral neuropathy. Watch out for several supplements that add up B6."}, "folato-vitamina-b9": {"oque": "B-complex vitamin; folic acid is the stable synthetic form used in supplements and in flour fortification.", "age": ["Supplies one-carbon units to form DNA bases.", "Together with B12, it recycles homocysteine into methionine."], "hist": "Its link to neural tube defects led to mandatory flour fortification in many countries from the 1990s onward.", "estudos": "Folic acid before conception reduces neural tube defects by about 70%. It did not consistently reduce cardiovascular disease.", "evitar": "High doses may mask B12 deficiency. Interacts with methotrexate, phenytoin and other drugs."}, "vitamina-k2-menaquinona": {"oque": "Group of fat-soluble vitamins (MK-4 to MK-13) produced by bacteria and present in fermented foods and animal products.", "age": ["Acts as a cofactor of the carboxylase that activates vitamin K-dependent proteins.", "These proteins include clotting factors, osteocalcin (bone) and matrix Gla protein (arteries)."], "hist": "Vitamin K was discovered in 1929 for its role in coagulation (the letter K from the German Koagulation).", "estudos": "Essential for coagulation. For bone and vascular calcification, K2 trials show mixed results and heterogeneous populations.", "evitar": "People taking warfarin should keep a stable intake and tell their doctor before using supplements."}, "vitamina-a-retinol": {"oque": "Fat-soluble vitamin found in liver, eggs and dairy products; plants provide carotenoids that the body converts into vitamin A.", "age": ["Retinal is part of rhodopsin, a pigment essential for vision in low light.", "Retinoic acid binds to RAR and RXR receptors and regulates the differentiation of skin and mucosal cells.", "It is also important for immunity."], "hist": "It was one of the first vitamins identified (1913). Deficiency is still a major cause of childhood blindness worldwide.", "estudos": "Supplementation in deficient populations reduces child mortality. In smokers, beta-carotene increased the risk of lung cancer in the ATBC and CARET studies.", "evitar": "Excess (hypervitaminosis A) damages the liver and bones and, during pregnancy, causes birth defects. Skin retinoids should not be combined with supplements."}, "vitamina-e-tocoferol": {"oque": "Group of eight fat-soluble compounds; alpha-tocopherol is the most active form in the human body.", "age": ["Stops lipid oxidation in cell membranes.", "Depends on other antioxidants, such as vitamin C, to return to its active form."], "hist": "Discovered in 1922 for its importance in rat reproduction. Interest in it as an antioxidant grew in the 1990s.", "estudos": "Trials such as HOPE, SELECT and ATBC showed no prevention of heart disease or cancer. SELECT suggested an increased risk of prostate cancer.", "evitar": "Avoid high doses with anticoagulants or before surgery. Well-nourished people rarely need to supplement."}, "niacina-vitamina-b3": {"oque": "B-complex vitamin (nicotinic acid and nicotinamide) that the body uses to make NAD+.", "age": ["It is converted into NAD+ and NADP+, which carry electrons in energy-producing reactions.", "At high pharmacological doses, it lowers LDL and triglycerides and raises HDL."], "hist": "It was identified as the cure for pellagra in 1937. High-dose niacin was one of the first therapies for dyslipidemia.", "estudos": "The AIM-HIGH and HPS2-THRIVE trials showed no additional cardiovascular benefit in people already on statins, and there were more adverse effects.", "evitar": "High doses cause flushing, itching, liver changes and increases in glucose and uric acid. Use requires monitoring."}, "nad": {"oque": "Nicotinamide adenine dinucleotide, a coenzyme present in all living cells; it is not a peptide.", "age": ["Accepts and donates electrons in energy-producing reactions in the mitochondria.", "It is consumed by sirtuins (repair and gene regulation) and PARPs (DNA repair).", "Tissue levels fall with age in animal models, which drives interest in replenishment."], "hist": "Discovered in 1906 by Harden and Young. Interest in the topic for aging grew after sirtuin studies in the 2000s.", "estudos": "In animals, raising NAD+ improved muscle and metabolic function. In humans, data on directly administered NAD+ are scarce and generally lack robust clinical outcomes.", "evitar": "Rapid intravenous infusions cause nausea, chest tightness and discomfort. There is a theoretical concern about use in cancer. It is not an approved medicine."}, "nmn-mononucleotideo-de-nicotinamida": {"oque": "A nucleotide that is a direct precursor of NAD+ and is present in small amounts in foods such as broccoli and avocado.", "age": ["It is converted into NAD+ by an enzyme called NMNAT.", "The exact mechanism by which it enters human cells is still debated."], "hist": "It drew attention after studies in aging mice. Its regulatory status in the US has changed more than once.", "estudos": "Small human trials showed increased blood NAD+ and, in some, a slight improvement in strength or insulin sensitivity, but results were inconsistent.", "evitar": "Long-term data are lacking; avoid in pregnancy and active cancer without professional guidance. Check the origin and purity of products."}, "nicotinamida-ribosideo-nr": {"oque": "A form of vitamin B3 that is an NAD+ precursor and was identified in milk.", "age": ["It is absorbed and converted into NMN and then into NAD+.", "It raises NAD+ in blood and tissues in humans in a dose-dependent manner."], "hist": "Recognized as an NAD+ precursor in 2004 by Charles Brenner. It is sold as a supplement in several countries.", "estudos": "Trials showed increased NAD+ with modest clinical effects on blood pressure, arterial stiffness and other outcomes; in Parkinson's disease and muscle disorders, results are still preliminary.", "evitar": "Generally well tolerated in short studies, with mild nausea and fatigue. Avoid in pregnancy and active cancer without guidance."}, "l-carnitina": {"oque": "A compound produced by the body and obtained from food. Medicinal levocarnitine treats specific deficiencies, not general supplement claims.", "age": ["It takes part in transporting certain fatty acids into the mitochondria.", "These fatty acids can be used to produce energy.", "The body also obtains carnitine from food, mainly of animal origin."], "hist": "Identified in the early 20th century, its metabolic role was clarified later. Levocarnitine has medicinal use in specific deficiencies.", "estudos": "Replacement is indicated for diagnosed deficiency. Benefits of supplements in people without deficiency are uncertain.", "evitar": "Kidney disease and medications require individual assessment; it may cause gastrointestinal discomfort."}, "acetil-l-carnitina": {"oque": "An acetylated form of carnitine found in tissues and studied in metabolism and nerve function. Research does not show general efficacy of supplements.", "age": ["It is part of the pool of carnitine forms in the body.", "Carnitine takes part in transporting fatty acids into the mitochondria.", "Additional effects on the nervous system are being investigated, with no guaranteed benefit."], "hist": "Studied in trials for neuropathy and some cognitive conditions. Indications and formulations vary between studies.", "estudos": "Clinical results vary by condition and study quality. No broad preventive or cognitive effect has been established.", "evitar": "It may cause gastrointestinal symptoms, agitation or body odor; safety data are limited."}, "acido-alfa-lipoico": {"oque": "A cofactor of mitochondrial energy-metabolism enzymes and a participant in redox reactions. Medicines used in some countries are distinct from supplements.", "age": ["It takes part in enzyme complexes that process nutrients to generate energy.", "Its oxidized and reduced forms take part in redox reactions.", "It is clinically studied mainly for diabetic neuropathy."], "hist": "Thioctic acid is used as a medicine in some European countries. It is also sold as a supplement of variable composition.", "estudos": "Trials for diabetic neuropathy are heterogeneous and depend on the formulation. No general benefit for longevity has been established.", "evitar": "It may lower glucose; diabetes treatment requires professional assessment."}, "n-acetilcisteina-nac": {"oque": "An acetylated form of cysteine and a precursor of glutathione. Medicines have specific indications, including paracetamol (acetaminophen) poisoning and mucolytic use.", "age": ["It supplies cysteine that can be used to synthesize glutathione.", "Glutathione takes part in cellular redox defenses.", "As a mucolytic, it can reduce the viscosity of secretions."], "hist": "Acetylcysteine is used as an antidote for paracetamol poisoning and in respiratory settings. Approval depends on the presentation and the country.", "estudos": "There is evidence for specific pharmaceutical indications. Results for other uses vary.", "evitar": "It may cause hypersensitivity and digestive symptoms; it may intensify the effects of nitroglycerin."}, "coenzima-q10": {"oque": "A cellular compound that takes part in the mitochondrial respiratory chain and in redox processes. Supplementation is studied in several conditions.", "age": ["It takes part in electron transfer in the mitochondrial chain.", "It contributes to ATP generation.", "It also takes part in cellular antioxidant processes."], "hist": "Coenzyme Q10 was identified as a mitochondrial component in the mid-20th century. Its supplementation is researched in different conditions.", "estudos": "Trials vary by condition and do not establish a general benefit. Some indications remain uncertain.", "evitar": "It may cause digestive symptoms and interact with warfarin; it does not replace prescribed treatment."}, "creatina": {"oque": "A molecule synthesized by the body and obtained from the diet, stored partly as phosphocreatine. It helps buffer rapidly used cellular energy.", "age": ["Creatine can receive a phosphate group and form phosphocreatine.", "Phosphocreatine helps regenerate ATP during rapid energy demands.", "Muscles store most of the body's creatine."], "hist": "Creatine was isolated in the 19th century and widely studied in exercise physiology. Supplements vary in form and quality.", "estudos": "There is evidence for some performance and body-composition outcomes. Clinical uses and other populations are still under study.", "evitar": "It can alter laboratory creatinine; kidney disease requires clinical interpretation."}, "taurina": {"oque": "A sulfur-containing compound abundant in tissues, not incorporated into proteins like an ordinary amino acid. It takes part in osmotic balance, bile salts and signaling.", "age": ["It helps regulate the balance of water and ions in cells.", "It takes part in the conjugation of bile acids.", "It also acts in neural and muscle signaling."], "hist": "Taurine was isolated in the 19th century and studied in nutrition and physiology. Supplementation effects vary with context.", "estudos": "Clinical studies are limited for many claims. No broad therapeutic efficacy has been established.", "evitar": "Data on prolonged supplementation and in clinical groups are limited."}, "glicina": {"oque": "An amino acid used to build proteins, creatine and glutathione. In the nervous system, it acts as an inhibitory neurotransmitter in some regions and as an NMDA co-agonist.", "age": ["It is incorporated into proteins and metabolic molecules.", "It can act on glycine receptors in the nervous system.", "It also works as an NMDA co-agonist at specific sites."], "hist": "Glycine has been known as an amino acid since the 19th century. Its role as a neurotransmitter was characterized later.", "estudos": "Small studies on sleep and metabolism do not establish an effective treatment. Dietary intake and body production are part of normal metabolism.", "evitar": "It may cause gastrointestinal discomfort; data on prolonged use are limited."}, "omega-3-epa-dha": {"oque": "EPA and DHA are fatty acids found mainly in fish and some algae products. Purified medicines have different indications from ordinary supplements.", "age": ["EPA and DHA are incorporated into cell membranes.", "They can serve as precursors of lipid mediators.", "The amount varies between foods, supplements and medicines."], "hist": "Studies of marine oils led to pharmaceutical omega-3 formulations. The FDA approved specific products for defined indications.", "estudos": "Evidence depends on the product, population and outcome. One medicine does not demonstrate equivalent efficacy for any supplement.", "evitar": "Pharmacological doses may affect bleeding or atrial fibrillation in some groups."}, "citicolina": {"oque": "Also called CDP-choline, it is an intermediate of choline and phospholipid metabolism. It is studied in neurological conditions without universal approval for these uses.", "age": ["After ingestion, it supplies choline and cytidine to metabolism.", "These components take part in the synthesis of membrane phospholipids.", "Choline is also a precursor of acetylcholine."], "hist": "Citicoline was developed and investigated in neurological diseases. Availability and regulatory status vary by country.", "estudos": "Trials in stroke and cognition had inconsistent results. No general benefit has been confirmed.", "evitar": "It may cause headache, digestive symptoms or insomnia; safety depends on the context."}, "ergotioneina": {"oque": "A sulfur-containing compound found in some foods, especially mushrooms, and carried into tissues by a specific protein. Its role as a supplement is under investigation.", "age": ["It is obtained mainly from food.", "A specific cellular transporter facilitates its entry into some tissues.", "Redox properties are being investigated, without proving disease prevention."], "hist": "Ergothioneine was isolated from fungi in the early 20th century. Research examines its transport and biological functions.", "estudos": "Clinical studies are preliminary and do not demonstrate preventive or longevity benefit.", "evitar": "The safety of prolonged supplementation has not been defined."}, "resveratrol": {"oque": "A polyphenol present in some plants, including grapes. Activity in cells and animals does not prove clinical benefit or increased longevity.", "age": ["It is absorbed and rapidly metabolized after ingestion.", "In experimental models it influences several cellular pathways.", "The relevance of these changes to human health remains uncertain."], "hist": "Resveratrol gained attention from experimental studies on aging and metabolism. Human trials evaluated various outcomes.", "estudos": "Human studies are heterogeneous and do not prove disease prevention or life extension.", "evitar": "It may interact with medicines, including anticoagulants; the safety of concentrated doses is uncertain."}, "pterostilbeno": {"oque": "A polyphenol related to resveratrol, found in small amounts in some plants. Most claims come from preclinical research.", "age": ["It is investigated for redox properties in models.", "It may affect metabolic signaling in cells and animals.", "It is not known whether these effects translate into clinical benefit in people."], "hist": "Pterostilbene was first studied in the laboratory and in animals. Available clinical data are scarce.", "estudos": "There is no evidence of benefit for longevity; human studies are insufficient.", "evitar": "Prolonged safety and interactions of concentrated supplements are poorly known."}, "urolitina-a": {"oque": "A metabolite formed by some gut microbiotas from compounds in certain foods. The ability to produce it varies between people.", "age": ["Some foods provide precursors such as ellagitannins.", "Certain microbiotas transform these precursors into urolithins.", "Urolithin A is studied for a possible link to mitophagy, with no guaranteed effect."], "hist": "It was characterized as a dietary metabolite and studied in safety and muscle-function trials.", "estudos": "Early trials do not demonstrate longevity or lasting clinical benefit.", "evitar": "Gut production varies; data on prolonged supplementation are limited."}, "espermidina": {"oque": "A polyamine produced by cells and present in foods. It takes part in cellular processes and is investigated for a possible link to autophagy.", "age": ["It takes part in regulating cell growth and function.", "Autophagy is a process of recycling cellular components.", "The mechanistic association does not prove a benefit of supplementation."], "hist": "Spermidine has been studied in cell biology for decades and gained attention in aging research.", "estudos": "Population observations and early studies do not demonstrate life extension through supplementation.", "evitar": "Effects of prolonged use and in chronic diseases are poorly known."}, "pqq-pirroloquinolina-quinona": {"oque": "PQQ is a redox compound studied in cells and animals. Claims about mitochondrial biogenesis do not equal demonstrated clinical benefit.", "age": ["It is investigated for taking part in redox reactions in models.", "Preclinical studies examine mitochondrial signaling.", "The importance of these effects in humans remains uncertain."], "hist": "PQQ was characterized as a microbial cofactor and later evaluated in nutritional studies.", "estudos": "Human trials are small and do not prove disease prevention or longevity.", "evitar": "The safety of prolonged supplementation is poorly characterized."}, "fisetina": {"oque": "A flavonoid present in some plant foods and studied for antioxidant effects and effects on senescent cells. Clinical senolytic activity has not been established.", "age": ["It is found in foods in variable amounts.", "In models, it may alter cellular stress and senescence signals.", "Preclinical findings do not demonstrate safe elimination of senescent cells in humans."], "hist": "Fisetin is studied as a flavonoid and in preclinical research on cellular senescence.", "estudos": "Senolytic evidence is mainly from laboratory and animal work; human studies do not confirm benefit.", "evitar": "The safety and interactions of concentrated supplements are uncertain."}, "quercetina": {"oque": "A flavonoid present in fruits, vegetables and other plants. Antioxidant activity in models does not mean efficacy against disease in humans.", "age": ["It is obtained from food and also sold in supplements.", "In experimental models, it interacts with several cellular pathways.", "Absorption depends on the chemical form and the food matrix."], "hist": "Quercetin is known as a plant pigment and is investigated in nutritional and clinical studies.", "estudos": "Small, heterogeneous trials do not demonstrate broad preventive benefit or life extension.", "evitar": "It may interact with medicines; the prolonged safety of concentrated doses is uncertain."}, "slu-pp-332": {"oque": "An experimental molecule described as an agonist of ERR receptors, which regulate metabolic genes. Preclinical findings do not show that it replaces exercise.", "age": ["The molecule activates ERR receptors in experimental models.", "ERRs regulate gene-expression programs related to metabolism.", "Results in animals do not establish efficacy or safety in humans."], "hist": "SLU-PP-332 was described in preclinical research on ERR receptors and metabolism. There is no approved medicine containing this compound.", "estudos": "Preclinical evidence; no clinical benefit has been demonstrated in humans.", "evitar": "Human safety, long-term effects and the composition of research products are unknown."}, "5-amino-1mq": {"oque": "An experimental molecule investigated as an inhibitor of NNMT, an enzyme of nicotinamide metabolism. It is not a proven exercise mimetic.", "age": ["In preclinical studies, it inhibits NNMT.", "This inhibition may alter metabolic pathways in models.", "The results do not prove weight loss, physical improvement or human safety."], "hist": "5-amino-1MQ was studied in cell and animal models of metabolism. There is no approved medicine containing this compound.", "estudos": "Preclinical evidence only; clinical efficacy and safety have not been established.", "evitar": "Human data are insufficient; the quality of research products is unknown."}, "magnesio": {"oque": "An essential mineral present in bones and cells. It takes part in hundreds of enzymatic reactions, energy production and nerve and muscle function.", "age": ["It acts as a cofactor for enzymes that use ATP.", "It helps regulate muscle contraction and nerve transmission.", "It contributes to bone structure and the balance of other electrolytes."], "hist": "The importance of magnesium in nutrition and neuromuscular function has been known for decades. Supplements and medicinal salts differ in absorption and tolerability.", "estudos": "Replacement corrects deficiency and is indicated in defined clinical settings. For cramps, sleep or disease prevention in people without deficiency, results vary and do not justify general promises.", "evitar": "In kidney disease, accumulation can be dangerous. Supplemental doses may cause diarrhea and interfere with the absorption of some antibiotics and levothyroxine."}, "zinco": {"oque": "An essential mineral found in many enzymes and proteins. It is needed for immunity, growth, wound healing and DNA synthesis.", "age": ["It is part of the structure of proteins that regulate gene expression.", "It is needed for cell division and for immune cells to function.", "It contributes to taste, smell and tissue repair."], "hist": "Zinc deficiency was recognized as a human nutritional problem in the 20th century. Today the mineral is supplied by foods, supplements and specific medicines.", "estudos": "Replacement is useful in confirmed or probable deficiency and in selected clinical situations. Broad preventive use or use to treat colds has variable benefit and depends on context and formulation.", "evitar": "Excessive, prolonged use can cause copper deficiency, anemia and neurological changes. It may reduce the absorption of some antibiotics; tell your healthcare professional about supplements."}, "selenio": {"oque": "An essential mineral incorporated into selenoproteins. Some of these proteins protect cell components from oxidation and take part in thyroid hormone metabolism.", "age": ["It is incorporated as selenocysteine into antioxidant enzymes, such as glutathione peroxidases.", "It helps control oxidation and reduction reactions in cells.", "It takes part in enzymes that transform thyroid hormones."], "hist": "Selenium was recognized as an essential nutrient after its roles in human enzymes were identified. Both deficiency and excess can cause problems.", "estudos": "Correcting deficiency is important. In people with adequate intake, trials do not show a consistent benefit of supplementation in preventing cancer or cardiovascular disease.", "evitar": "Chronic excess can cause selenosis, with changes in hair, nails, breath and the nervous system. The concentration in foods and products varies."}, "ferro": {"oque": "An essential mineral that forms part of hemoglobin and myoglobin and takes part in enzymes. The body recycles much of the iron from aging red blood cells.", "age": ["Hemoglobin uses iron to carry oxygen in the blood.", "Myoglobin stores oxygen in muscle.", "Iron-containing enzymes take part in cellular respiration and energy production."], "hist": "The link between iron shortage and anemia has been known since ancient medicine. Deficiency can result from blood loss, increased need or inadequate absorption.", "estudos": "Treating deficiency and iron-deficiency anemia improves stores and hemoglobin. The cause of the deficiency should be investigated; iron does not treat anemia of any origin.", "evitar": "Do not use without an assessment of deficiency, since overload can damage the liver, heart and other organs. Keep iron-containing products away from children; accidental ingestion can be fatal."}, "tiamina-vitamina-b1": {"oque": "Thiamine, or vitamin B1, is a water-soluble vitamin needed for energy metabolism and for nerve and muscle function.", "age": ["It is converted into thiamine pyrophosphate, its active coenzyme form.", "It helps enzymes metabolize glucose and certain amino acids.", "It especially supports tissues with high energy demand, such as the brain and heart."], "hist": "Thiamine deficiency helped identify the cause of beriberi. Its clinical importance is especially recognized in malnutrition, alcoholism and some malabsorption conditions.", "estudos": "Replacement prevents or treats deficiency and must be prompt when Wernicke encephalopathy is suspected. There is no evidence that it increases energy or performance in people with adequate nutritional status.", "evitar": "The injectable route can rarely cause a severe allergic reaction and requires an appropriate setting. Risk situations and neurological symptoms need medical evaluation."}, "riboflavina-vitamina-b2": {"oque": "Riboflavin, or vitamin B2, is a precursor of FMN and FAD, coenzymes used in energy-producing reactions.", "age": ["It is converted into FMN and FAD inside cells.", "These coenzymes take part in oxidation-reduction reactions.", "It also contributes to the metabolism of other vitamins and to the maintenance of tissues."], "hist": "Riboflavin was identified in the early 20th century, and its deficiency became linked to changes in skin and mucous membranes. It is obtained from food and fortification.", "estudos": "Supplementation treats deficiency. Migraine-prevention trials suggest benefit in some patients, but the response varies and does not mean it is a universal treatment.", "evitar": "It is generally well tolerated; intense yellow urine after intake is expected. Tell the laboratory about supplements, since some tests may be affected."}, "biotina-vitamina-b7": {"oque": "Biotin, or vitamin B7, is a water-soluble vitamin that acts as a cofactor for metabolic enzymes.", "age": ["It binds to carboxylases that transfer carbon dioxide in biochemical reactions.", "It takes part in the metabolism of fatty acids, glucose and amino acids.", "Deficiency is rare, but it can affect skin, hair and the nervous system."], "hist": "Biotin was recognized as a nutritional factor in growth and metabolism studies. Deficiency can occur in rare conditions, such as biotinidase deficiency.", "estudos": "Replacement is effective when there is a deficiency. There is no robust evidence of benefit for hair and nails in people without a deficiency; supplement claims exceed the available data.", "evitar": "High doses can interfere with laboratory tests, including troponin and hormone tests, producing false results. Inform the laboratory and the health professional before tests."}, "exenatida": {"oque": "Synthetic peptide related to exendin-4, a GLP-1 receptor agonist. It is used in some formulations for type 2 diabetes.", "age": ["It activates GLP-1 receptors in the pancreas and other tissues.", "It increases insulin secretion when glucose is elevated and reduces glucagon.", "It slows gastric emptying and may reduce appetite."], "hist": "Exenatide was one of the first GLP-1 agonists approved for type 2 diabetes. Short-acting and extended-release formulations exist, with labels and availability that vary by country.", "estudos": "Clinical trials show improved blood glucose and modest average weight loss. Benefits and risks depend on the formulation, the clinical condition and the associated medicines.", "evitar": "It can cause gastrointestinal symptoms and hypoglycemia when combined with insulin or sulfonylureas. It is not indicated in some digestive diseases; consult the label and a professional."}, "lixisenatida": {"oque": "GLP-1 receptor agonist peptide used in some markets to treat type 2 diabetes.", "age": ["It activates the GLP-1 receptor and increases insulin in a glucose-dependent manner.", "It reduces glucagon after meals.", "It slows gastric emptying, contributing to postprandial glucose control."], "hist": "Lixisenatide is a once-daily GLP-1 agonist studied and registered in different jurisdictions. Combination formulations and availability vary by country.", "estudos": "Studies show glycemic improvement in type 2 diabetes, with a generally modest effect on weight. Cardiovascular benefit should not be extrapolated beyond the populations and outcomes studied.", "evitar": "Nausea and vomiting are common at the start. Hypoglycemia may occur with other antidiabetic drugs, and the absorption of oral medicines may change; check the label and local registration."}, "dulaglutida": {"oque": "Long-acting GLP-1 receptor agonist fusion protein, indicated for type 2 diabetes in markets where it is registered.", "age": ["It activates GLP-1 receptors and increases insulin when glucose is elevated.", "It reduces glucagon and slows gastric emptying.", "It may decrease appetite and food intake."], "hist": "Dulaglutide was developed to prolong the action of GLP-1 agonism. Cardiovascular trials expanded knowledge about its effects in people with type 2 diabetes.", "estudos": "Glycemic efficacy and weight reduction are demonstrated in trials. A cardiovascular study showed a reduction in events in a population with high-risk diabetes; this does not mean universal prevention.", "evitar": "It can cause nausea, diarrhea and biliary problems. Evaluation is needed in the case of persistent abdominal pain, gastroparesis or concomitant use of insulin."}, "maridebart-cafraglutida-maritide": {"oque": "Experimental long-acting biologic with GLP-1R agonist and GIPR antagonist activity. It is not an approved drug for general use.", "age": ["It activates the GLP-1 receptor, a pathway involved in satiety and glucose control.", "It blocks the GIP receptor, but the clinical role of this antagonism is still under investigation.", "The combination seeks to influence appetite and weight through distinct incretin pathways."], "hist": "The compound, formerly known as AMG 133, is in clinical development for obesity and other metabolic conditions. The evidence and the phase should be checked in up-to-date trial registries.", "estudos": "Early studies observed weight reduction in participants, but they do not establish a definitive comparison or long-term safety. Confirmatory trials are needed.", "evitar": "Not approved for marketing or self-medication. Gastrointestinal effects were observed, and the full safety profile, including GIP antagonism, is still under study."}, "petrelintida": {"oque": "Long-acting amylin analog under clinical investigation for weight management. It is not approved for marketing.", "age": ["It mimics part of the actions of amylin, a hormone co-secreted with insulin.", "It acts on pathways related to satiety in the nervous system.", "It may slow gastric emptying and reduce food intake."], "hist": "Petrelintide was developed as an amylin analog with a long-acting profile. Its development and clinical phase should be followed in current registries and publications.", "estudos": "Phase 2 trials investigate weight and tolerability. Early results do not prove lasting efficacy or safety for use outside clinical trials.", "evitar": "It is experimental and should not be obtained or used outside authorized research. Nausea and other digestive effects are possible; combinations with other drugs are not established."}, "eloralintida": {"oque": "Experimental peptide agonist of amylin receptors, investigated for metabolic diseases and weight management.", "age": ["It activates receptors related to amylin signaling.", "It may increase satiety by acting on nervous system circuits.", "Its gastric and metabolic action is still being characterized in studies."], "hist": "Eloralintide is in clinical development and is not an approved medicine. Its phase status may change as new trials are registered.", "estudos": "The available studies are early and assess safety and signs of efficacy. There is not yet enough evidence to determine lasting clinical benefit.", "evitar": "Do not use outside authorized clinical trials. Safety in pregnancy, coexisting diseases, combinations and prolonged use is not established."}, "orforglipron": {"oque": "Oral small-molecule GLP-1 receptor agonist. It is not a peptide, even though it acts on the same receptor as incretin peptide medicines.", "age": ["It binds to and activates the GLP-1 receptor.", "It increases insulin secretion when glucose is elevated and reduces glucagon signals.", "It may slow gastric emptying and decrease appetite."], "hist": "Developed as a non-peptide oral GLP-1 agonist. The development phase and eventual regulatory status should be checked in up-to-date official sources.", "estudos": "Phase 3 trials assess blood glucose, weight and safety. Trial results are not equivalent to approval or an indication for individual use.", "evitar": "It is experimental according to the reported phase and should not be used outside authorized studies. Possible gastrointestinal effects and class risks require a full regulatory evaluation."}, "lanreotida": {"oque": "Synthetic somatostatin analog that reduces hormone secretion by activating somatostatin receptors.", "age": ["It preferentially binds to somatostatin receptor subtypes.", "It reduces GH release and, consequently, may reduce IGF-1.", "It also decreases gastrointestinal secretions and those of some neuroendocrine tumors."], "hist": "Lanreotide has been used for decades in acromegaly and neuroendocrine tumors, with depot formulations. Precise indications vary by country and formulation.", "estudos": "There is clinical evidence for biochemical control of acromegaly and control of some neuroendocrine tumors. The response depends on the tumor, the indication and the formulation.", "evitar": "It can alter glucose, heart rhythm and the gallbladder. Administration and follow-up must follow the label and a specialized team."}, "pasireotida": {"oque": "Somatostatin analog with affinity for several receptor subtypes. It is used in selected hormonal indications.", "age": ["It activates somatostatin receptors in the pituitary and other tissues.", "It may reduce ACTH and cortisol in Cushing's disease.", "It may also reduce GH and IGF-1 secretion in acromegaly."], "hist": "Pasireotide was developed to target a broader profile of somatostatin receptors than earlier analogs. Formulations and indications differ between countries.", "estudos": "Trials support its use in selected patients with Cushing's disease and acromegaly. Hyperglycemia is an important adverse effect that may limit treatment.", "evitar": "It requires monitoring of glucose, the gallbladder and, depending on the case, the QT interval. Do not start or adjust without specialized evaluation and consulting the label."}, "vasopressina": {"oque": "Peptide hormone, also called arginine vasopressin, produced in the hypothalamus and released by the posterior pituitary.", "age": ["It activates V1a receptors and constricts blood vessels.", "It activates V2 receptors in the kidneys and increases water reabsorption.", "Its secretion is regulated by blood osmolality and circulating volume."], "hist": "Vasopressin was identified as a regulator of blood pressure and water balance. The pharmaceutical form has hospital uses and indications that vary between jurisdictions.", "estudos": "There are established clinical uses in specific settings, such as hospital hemodynamic support. Use and evidence should not be extrapolated to unapproved purposes.", "evitar": "It can cause ischemia, arrhythmia and water retention with a drop in sodium. Parenteral administration requires clinical and electrolyte monitoring."}, "terlipressina": {"oque": "Synthetic vasopressin analog and prodrug of lysine vasopressin, with predominantly V1 vasoconstrictor action.", "age": ["It activates vascular V1 receptors and reduces flow in splanchnic territories.", "It may raise effective arterial volume and mean arterial pressure.", "In hepatorenal syndrome, it may improve renal perfusion in selected patients."], "hist": "Terlipressin is used in several countries for different conditions, but authorizations are not uniform. The FDA approved Terlivaz for adults with hepatorenal syndrome type 1 with rapid reduction in kidney function, and this approval does not cover other indications.", "estudos": "Trials showed improved kidney function in selected patients with hepatorenal syndrome; the clinical benefit depends on the population and does not eliminate serious risks.", "evitar": "There is a regulatory warning of serious or fatal respiratory failure and ischemia. Hospital use requires careful selection, respiratory assessment and confirmation of registration and indication in the country."}, "degarelix": {"oque": "Peptide GnRH receptor antagonist, used in some jurisdictions for advanced prostate cancer.", "age": ["It blocks GnRH receptors in the pituitary.", "It reduces the secretion of LH and FSH and testicular testosterone production.", "Unlike GnRH agonists, it does not usually cause an initial testosterone surge."], "hist": "Degarelix was developed as a long-acting GnRH antagonist. Its approval and formulation depend on the market and the registered indication.", "estudos": "Clinical trials support rapid testosterone suppression in hormone-sensitive prostate cancer. The choice depends on the oncological picture and the available alternatives.", "evitar": "It can cause local reactions and changes in glucose and QT; hormonal suppression also affects bones. It requires oncological follow-up."}, "cetrorrelix": {"oque": "GnRH antagonist used in assisted reproduction protocols to prevent premature LH release.", "age": ["It reversibly blocks GnRH receptors in the pituitary.", "It reduces LH and FSH during the period of action.", "It helps prevent spontaneous ovulation before the planned moment in assisted fertilization."], "hist": "Cetrorelix was developed to control the timing of ovulation in assisted reproduction treatments. The requested name, Cetrorrelix, corresponds to the active ingredient cetrorelix.", "estudos": "There is evidence of efficacy within supervised fertility protocols. It is not a standalone treatment for infertility and should not be extrapolated to other uses.", "evitar": "Local reactions or hypersensitivity may occur. Ovarian hyperstimulation syndrome is a risk of the fertility protocol and requires specialized follow-up."}, "triptorrelina": {"oque": "GnRH agonist that suppresses sex hormones when given continuously in appropriate formulations.", "age": ["It initially stimulates pituitary GnRH receptors and may raise LH and FSH.", "Continuous exposure desensitizes these receptors.", "Sex hormone production decreases after the initial phase."], "hist": "Triptorelin is marketed in depot formulations for specific oncological and gynecological indications. The formulations are not interchangeable without guidance.", "estudos": "Evidence is established for specific hormone-sensitive indications, with efficacy depending on the disease and the formulation. Hormonal suppression has relevant systemic effects.", "evitar": "Initial worsening of symptoms, bone loss, metabolic changes and QT prolongation may occur. Use requires an indication and specialized follow-up."}, "goserelina": {"oque": "GnRH agonist given in depot formulations to suppress sex hormones in selected indications.", "age": ["It initially stimulates the pituitary and may cause a transient rise in LH and FSH.", "With continuous exposure, it reduces the sensitivity of pituitary receptors.", "It decreases estrogen or testosterone production, depending on the physiological context."], "hist": "Goserelin is used in oncology and gynecology as depot implants. The duration and authorized indications vary according to the formulation and the country.", "estudos": "Trials and clinical use support specific oncological and gynecological indications. The benefit must be weighed against the effects of hormonal suppression and monitored by a clinical team.", "evitar": "It can cause hot flashes, bone loss, metabolic changes and a reaction at the site. Prostate cancer may transiently worsen at the start; it requires supervision."}, "bivalirudina": {"oque": "Synthetic peptide anticoagulant related to hirudin. It directly inhibits thrombin, a central enzyme in clot formation.", "age": ["It binds to thrombin and reduces its enzymatic activity.", "It decreases the conversion of fibrinogen into fibrin.", "It also reduces thrombin-mediated platelet activation."], "hist": "It was developed as a direct-acting alternative to heparin in cardiovascular settings. Its current use is defined by indication and hospital protocol.", "estudos": "There is clinical evidence and approval for specific cardiovascular indications. The choice in procedures depends on bleeding risk, kidney function and the available alternatives.", "evitar": "It can cause serious bleeding and requires assessment of kidney function. It is not a medicine for use without hospital supervision."}, "ziconotida": {"oque": "Synthetic peptide inspired by the conotoxin of a marine cone snail. It is a non-opioid analgesic administered directly into the fluid around the spinal cord.", "age": ["It blocks N-type neuronal calcium channels, called CaV2.2.", "It reduces the release of neurotransmitters involved in pain transmission.", "Intrathecal administration limits systemic exposure, but does not eliminate neurological effects."], "hist": "The molecule was derived from studies of Conus magus toxins. The intrathecal formulation was approved by the FDA for severe chronic pain in selected patients.", "estudos": "Clinical trials support its use in severe chronic pain, but the margin between benefit and adverse effects requires careful adjustment and specialized monitoring.", "evitar": "It can cause confusion, hallucinations and serious cognitive or psychiatric changes. It is contraindicated in people with a history of psychosis and must not be given by the systemic route."}, "linaclotida": {"oque": "Oral peptide that activates guanylate cyclase C on the intestinal surface. Its systemic absorption is minimal under usual conditions.", "age": ["It activates the guanylate cyclase C receptor in the intestinal mucosa.", "It increases local cyclic GMP and the secretion of chloride and bicarbonate.", "It raises the water content of stool and may reduce visceral pain."], "hist": "It was developed for constipation and symptoms of irritable bowel syndrome with constipation. Indications and age ranges vary according to the label in each country.", "estudos": "Clinical trials support efficacy for the approved indications. Diarrhea is a frequent adverse event and can lead to dehydration.", "evitar": "Do not use in children under 2 years or in known or suspected gastrointestinal obstruction. Seek evaluation if severe diarrhea or signs of dehydration occur."}, "icatibanto": {"oque": "Synthetic peptide that blocks the bradykinin B2 receptor. It is used to treat acute attacks of hereditary angioedema.", "age": ["It competes with bradykinin for the B2 receptor.", "It reduces signs of vasodilation and increased permeability associated with the attack.", "It is given subcutaneously according to the label and clinical guidance."], "hist": "It was developed to interfere with the bradykinin pathway, which is important in hereditary angioedema attacks. Approved formulations exist in different countries, with local registration to be confirmed.", "estudos": "Clinical trials support the treatment of acute attacks in the approved indications. The intensity of the response and the timing of assessment vary between patients.", "evitar": "Local reactions are common. Swelling of the tongue or throat, difficulty breathing or rapid worsening requires emergency care; the medicine does not replace airway management."}, "enfuvirtida": {"oque": "Antiretroviral peptide that prevents HIV-1 from entering susceptible cells. It is used in combination with other antiretrovirals.", "age": ["It binds to the HR1 region of the viral gp41 protein.", "It prevents structural changes needed for fusion between the viral envelope and the cell membrane.", "Combination with other antiretrovirals reduces replication and helps limit resistance."], "hist": "It was one of the first HIV-1 fusion inhibitors approved by the FDA. It is given subcutaneously and may cause repeated local reactions.", "estudos": "Trials and clinical experience support its use in combination regimens, especially in selected treatment situations. Viral susceptibility and treatment history influence the response.", "evitar": "It must not be used alone. Hypersensitivity reactions, nodules and infections at the injection site require clinical attention."}, "difelikefalina": {"oque": "Peptide that is a selective kappa opioid receptor agonist with a predominantly peripheral action. The approved formulation is used for pruritus associated with chronic kidney disease in adults on hemodialysis.", "age": ["It activates peripheral kappa receptors involved in itch signaling.", "It modulates sensory signals without being a typical mu agonist.", "It is given intravenously during the hemodialysis session, according to the label."], "hist": "The FDA approved difelikefalin for moderate to severe pruritus associated with chronic kidney disease in adults undergoing hemodialysis. This indication should not be extrapolated to other causes of itching.", "estudos": "Clinical trials in hemodialysis showed reduced pruritus in some patients. Drowsiness, dizziness and changes in mental status should be monitored.", "evitar": "Sedatives and other central nervous system depressants can increase drowsiness and the risk of falls. Safety in populations outside the approved indication should not be assumed."}, "cerebrolisina": {"oque": "Complex preparation of peptides and amino acids derived from pig brain, not a single-sequence molecule. It is marketed and used in some countries for neurological conditions.", "age": ["It contains a mixture of peptide fragments and amino acids.", "Neurotrophic or neuroprotective effects are proposed, but they do not define a proven clinical mechanism.", "The mixture cannot be reduced to a single receptor or molecular target."], "hist": "It is used in some countries, while it has no FDA approval. The complex composition makes it hard to compare products and to attribute effects to specific components.", "estudos": "It has been investigated in studies of stroke and other neurological diseases, with heterogeneous results. Reviews and trials do not support definitive benefit in all indications; registration and evidence vary by country.", "evitar": "It does not replace established neurological treatments or emergency care. The biological origin, composition and adverse effects call for caution; check the registration with the local regulatory agency."}, "timalina": {"oque": "Preparation described as thymus peptides and used in Russia as an immunomodulator. Its composition and clinical mechanism are not well defined.", "age": ["Thymic peptides are proposed as modulators of T-cell maturation.", "Effects on other immune cells have been suggested, but are not well characterized.", "The mixture and the activity may vary between products and sources."], "hist": "Thymalin has reported use in Russia. Use in one country does not demonstrate approval or efficacy in others, and the available evidence is limited.", "estudos": "The reported stage is preclinical in animals; the literature is limited and there is no robust demonstration of clinical benefit. Efficacy should not be inferred from the proposed mechanism.", "evitar": "Safety, composition, interactions and effects in autoimmune diseases are not well established. Check the local registration and do not replace prescribed therapies."}, "timopentina": {"oque": "Synthetic pentapeptide derived from a region of thymopoietin, investigated for possible effects on T-lymphocyte function. Its current clinical status varies by country.", "age": ["It mimics part of a thymopoietin sequence.", "It has been studied as a modulator of T-lymphocyte differentiation and activity.", "Effects depend on the context and are not equivalent to a proven broad immune stimulation."], "hist": "Thymopentin was evaluated in clinical studies, including advanced phases, and used in some countries. The current regulatory situation should be checked for each country and indication.", "estudos": "The history of trials, including phase 3 studies, is not enough to conclude current efficacy or broad approval. The quality and relevance of the data vary by indication.", "evitar": "Long-term safety data and interactions are limited. Caution is needed in autoimmune diseases, transplants or use of immunosuppressants, with professional evaluation."}}, "es": {"semaglutida": {"oque": "Péptido sintético parecido al GLP-1, hormona que el intestino libera después de las comidas. Fue modificado para durar días en el cuerpo, en lugar de minutos.", "age": ["Se une al receptor de GLP-1 en el páncreas, el cerebro y el estómago.", "En el páncreas, estimula la liberación de insulina solo cuando la glucosa está alta y reduce el glucagón.", "En el cerebro (hipotálamo), aumenta la saciedad y disminuye el hambre.", "En el estómago, retrasa el vaciamiento, prolongando la sensación de estar lleno."], "hist": "Desarrollada por Novo Nordisk a partir del GLP-1 humano, con una cadena lateral de ácido graso que se une a la albúmina y prolonga su acción. Aprobada para la diabetes tipo 2 en 2017 y para la obesidad en 2021 (FDA).", "estudos": "Los programas SUSTAIN (diabetes) y STEP (obesidad) mostraron descenso de la glucemia y una pérdida de peso relevante; el estudio SELECT señaló una reducción de eventos cardiovasculares en personas con obesidad y enfermedad cardíaca.", "evitar": "Antecedentes personales o familiares de carcinoma medular de tiroides o neoplasia endocrina múltiple tipo 2, pancreatitis previa, embarazo. Los efectos gastrointestinales son frecuentes; su uso requiere receta y seguimiento médico."}, "tirzepatida": {"oque": "Péptido de 39 aminoácidos que imita dos hormonas intestinales a la vez: GIP y GLP-1 (agonista dual).", "age": ["Activa los receptores de GLP-1 y de GIP, ambos implicados en el control de la glucosa y del apetito.", "Aumenta la insulina de forma dependiente de la glucosa y reduce el apetito en el cerebro.", "La combinación de ambos receptores parece sumar el efecto sobre el peso en comparación con el GLP-1 solo."], "hist": "Desarrollada por Eli Lilly. Aprobada por la FDA para la diabetes tipo 2 en 2022 y para la obesidad en 2023.", "estudos": "Los programas SURPASS (diabetes) y SURMOUNT (obesidad) mostraron reducciones notables de la HbA1c y del peso corporal, comparables o superiores a las de otras terapias comparadas.", "evitar": "Los mismos cuidados de la clase: antecedentes de carcinoma medular de tiroides, pancreatitis, embarazo. Las náuseas y la diarrea son frecuentes. Puede reducir la eficacia de los anticonceptivos orales al inicio del tratamiento."}, "ocitocina": {"oque": "Hormona natural de 9 aminoácidos producida en el hipotálamo y liberada por la hipófisis posterior. La forma farmacéutica es idéntica a la natural.", "age": ["Se une al receptor de oxitocina en el útero, aumentando la frecuencia y la fuerza de las contracciones.", "En las mamas, provoca la eyección de la leche durante la lactancia.", "En el cerebro, participa en comportamientos sociales, pero el uso de este efecto aún es experimental."], "hist": "Aislada y sintetizada por Vincent du Vigneaud en la década de 1950, logro que le valió el Nobel de Química de 1955: fue la primera hormona peptídica sintetizada.", "estudos": "El uso obstétrico (inducción del parto, control de la hemorragia posparto) está bien establecido. Los estudios sobre efectos conductuales (confianza, autismo, ansiedad) muestran resultados inconsistentes.", "evitar": "Solo para uso hospitalario. Los riesgos incluyen hiperestimulación uterina y retención de líquidos (intoxicación hídrica). No debe usarse sin supervisión obstétrica."}, "hormonio-do-crescimento-somatropina": {"oque": "Hormona del crecimiento humana recombinante, una proteína de 191 aminoácidos idéntica a la producida por la hipófisis.", "age": ["Se une al receptor de GH en varios tejidos, sobre todo en el hígado.", "El hígado responde produciendo IGF-1, que promueve el crecimiento de huesos y músculos.", "También actúa sobre el metabolismo, favoreciendo el uso de la grasa como energía."], "hist": "Antes de 1985 se extraía de hipófisis de cadáveres, lo que causó casos de enfermedad de Creutzfeldt-Jakob. Desde entonces se produce mediante ADN recombinante.", "estudos": "Eficaz en niños con deficiencia de GH y en otras indicaciones aprobadas (síndrome de Turner, insuficiencia renal crónica, etc.). En adultos sanos no hay beneficio comprobado y existen riesgos.", "evitar": "Cáncer activo, retinopatía diabética proliferativa y uso por personas sanas con fines estéticos o deportivos (prohibida por la AMA/WADA). Efectos: retención de líquidos, resistencia a la insulina."}, "liraglutida": {"oque": "Análogo del GLP-1 con cerca de un 97% de similitud con la hormona humana, de acción más prolongada que la natural.", "age": ["Activa el receptor de GLP-1, estimulando la insulina cuando la glucosa está alta.", "Reduce el apetito por su acción en el hipotálamo.", "Retrasa el vaciamiento gástrico."], "hist": "De Novo Nordisk; aprobada para la diabetes tipo 2 en 2010 (Victoza) y para la obesidad en 2014 (Saxenda). Fue una de las precursoras de la semaglutida.", "estudos": "El estudio LEADER mostró una reducción de eventos cardiovasculares en la diabetes tipo 2; los estudios SCALE mostraron una pérdida de peso moderada.", "evitar": "Antecedentes de carcinoma medular de tiroides o NEM2, pancreatitis, embarazo. Las náuseas son frecuentes al inicio."}, "insulina": {"oque": "Hormona de la glucosa compuesta por dos cadenas (A con 21 y B con 30 aminoácidos) unidas por puentes disulfuro.", "age": ["Se une al receptor de insulina en las células del músculo, el hígado y la grasa.", "Favorece la entrada de glucosa en las células y la síntesis de glucógeno.", "Reduce la producción de glucosa por el hígado, bajando la glucemia."], "hist": "Descubierta en 1921 por Banting y Best; fue el primer péptido usado como medicamento. Hoy se produce mediante ADN recombinante, con análogos de acción rápida y prolongada.", "estudos": "Estudios como el DCCT mostraron que el control intensivo de la glucosa reduce las complicaciones de la diabetes tipo 1.", "evitar": "El principal riesgo es la hipoglucemia (glucosa baja), que puede ser grave. Uso solo con receta y orientación para el ajuste de dosis."}, "teriparatida": {"oque": "Fragmento activo (aminoácidos 1–34) de la hormona paratiroidea humana, usado para tratar la osteoporosis.", "age": ["Administrada en picos intermitentes, activa los osteoblastos (células que forman hueso).", "Esto aumenta la masa ósea y la resistencia a las fracturas.", "A diferencia de la exposición continua, que favorece la pérdida ósea."], "hist": "Aprobada por la FDA en 2002 como el primer tratamiento anabólico (formador de hueso) para la osteoporosis.", "estudos": "Los ensayos mostraron una reducción de fracturas vertebrales y no vertebrales en mujeres posmenopáusicas.", "evitar": "Enfermedad de Paget, radioterapia ósea previa, cáncer óseo o metástasis, hipercalcemia. El tiempo total de uso es limitado."}, "tesamorelina": {"oque": "Análogo sintético de la GHRH (hormona liberadora de la hormona del crecimiento), con 44 aminoácidos.", "age": ["Estimula la hipófisis para que libere la propia GH del cuerpo.", "La GH aumenta el IGF-1, que contribuye a reducir la grasa visceral.", "Mantiene el ritmo natural de liberación de la GH."], "hist": "Aprobada por la FDA en 2010 (Egrifta) para reducir el exceso de grasa abdominal en personas con VIH y lipodistrofia.", "estudos": "Dos ensayos de fase 3 mostraron una reducción de la grasa visceral en personas que viven con VIH; el beneficio desaparece al suspender el uso.", "evitar": "Cáncer activo, embarazo y disfunción hipofisaria. Puede empeorar la tolerancia a la glucosa."}, "retatrutida": {"oque": "Péptido experimental que activa tres receptores a la vez: GLP-1, GIP y glucagón (agonista triple).", "age": ["Los componentes GLP-1 y GIP reducen el apetito y mejoran la glucemia.", "El receptor de glucagón puede aumentar el gasto de energía y reducir la grasa en el hígado."], "hist": "Desarrollada por Eli Lilly y aún en fase 3 (programa TRIUMPH); no está aprobada.", "estudos": "Los resultados de fase 2 mostraron una pérdida de peso muy notable, publicados en una revista de alto impacto; los datos de fase 3 aún se están completando.", "evitar": "No está aprobada: el uso fuera de ensayos clínicos no tiene seguridad establecida. Los efectos gastrointestinales fueron frecuentes en los estudios."}, "cagrilintida": {"oque": "Análogo de acción prolongada de la amilina, hormona que acompaña a la insulina y ayuda a controlar la saciedad.", "age": ["Activa receptores de amilina y calcitonina en el cerebro.", "Aumenta la saciedad y retrasa el vaciamiento gástrico.", "Suele estudiarse en combinación con semaglutida (CagriSema)."], "hist": "De Novo Nordisk, en fase 3 para la obesidad (programa REDEFINE).", "estudos": "Los estudios de fase 2 mostraron pérdida de peso, con mayor efecto cuando se asocia a la semaglutida.", "evitar": "Aún no aprobada. Las náuseas fueron el efecto adverso más frecuente."}, "survodutida": {"oque": "Agonista dual de los receptores de glucagón y GLP-1, estudiado para la obesidad y la enfermedad hepática grasa (MASH).", "age": ["El componente GLP-1 reduce el apetito.", "El glucagón aumenta el gasto de energía y la quema de grasa en el hígado."], "hist": "Desarrollada por Boehringer Ingelheim; en fase 3 (programa SYNCHRONIZE).", "estudos": "La fase 2 mostró pérdida de peso y reducción de la grasa en el hígado.", "evitar": "No aprobada. Las náuseas y los vómitos fueron frecuentes."}, "mazdutida": {"oque": "Agonista dual de GLP-1 y glucagón desarrollado en China para la obesidad y la diabetes tipo 2.", "age": ["Reduce el apetito a través del GLP-1.", "Aumenta el gasto de energía a través del glucagón."], "hist": "Desarrollada por Innovent en colaboración con Lilly; en fase 3 en China.", "estudos": "Los estudios de fase 2 y de fase 3 iniciales mostraron pérdida de peso y mejora metabólica.", "evitar": "No aprobada por las principales agencias. Se esperan efectos gastrointestinales."}, "pramlintida": {"oque": "Análogo sintético de la amilina, usado junto con la insulina en las comidas.", "age": ["Retrasa el vaciamiento del estómago.", "Reduce la liberación de glucagón después de las comidas.", "Aumenta la saciedad."], "hist": "Aprobada por la FDA en 2005 (Symlin) para la diabetes tipo 1 y 2 en personas que usan insulina.", "estudos": "Mostró un descenso modesto de la HbA1c y una pérdida de peso discreta.", "evitar": "Tiene una advertencia sobre hipoglucemia grave cuando se asocia a la insulina; contraindicada en la gastroparesia."}, "setmelanotida": {"oque": "Agonista del receptor MC4R, que regula el hambre y el gasto energético, para formas genéticas raras de obesidad.", "age": ["Activa el receptor MC4R en el hipotálamo, en una vía que normalmente señala saciedad.", "En las variantes genéticas en las que esta vía es defectuosa, restaura parte de la señal."], "hist": "Aprobada por la FDA en 2020 (Imcivree) para la obesidad por deficiencia de POMC, PCSK1 o LEPR, y después para el síndrome de Bardet-Biedl.", "estudos": "En personas con estas deficiencias raras hubo una pérdida de peso y una reducción del hambre relevantes.", "evitar": "El oscurecimiento de la piel y las reacciones en el lugar de la inyección son frecuentes; uso restringido a indicaciones genéticas específicas."}, "dasiglucagona": {"oque": "Análogo estable del glucagón, listo para usar, para tratar la hipoglucemia grave.", "age": ["Activa el receptor de glucagón en el hígado.", "El hígado libera la glucosa almacenada, elevando la glucemia."], "hist": "Aprobada por la FDA en 2021 (Zegalogue) para la hipoglucemia grave en personas con diabetes.", "estudos": "Los ensayos mostraron la recuperación de la glucemia en pocos minutos, comparable al glucagón tradicional.", "evitar": "Precaución en feocromocitoma e insulinoma. Las náuseas y los vómitos son frecuentes."}, "gonadorelina-gnrh": {"oque": "Hormona liberadora de gonadotropinas, con 10 aminoácidos, que dirige a la hipófisis en el control de las hormonas reproductivas.", "age": ["Estimula la hipófisis para que libere FSH y LH.", "El patrón en pulsos es esencial: los pulsos mantienen la función y la exposición continua la bloquea."], "hist": "Su estructura fue descubierta por Schally y Guillemin (Nobel de 1977).", "estudos": "Se usa en diagnóstico y en protocolos específicos de fertilidad; sus análogos tienen un uso mucho mayor.", "evitar": "Uso solo en un contexto médico especializado."}, "leuprorrelina": {"oque": "Análogo de la GnRH que, usado de forma continua, deja de estimular y pasa a suprimir las hormonas sexuales.", "age": ["Inicialmente provoca una elevación breve de LH y FSH.", "Con la exposición continua, los receptores se desensibilizan y la producción de testosterona o estrógeno disminuye."], "hist": "En uso desde la década de 1980, es la base del tratamiento hormonal del cáncer de próstata avanzado.", "estudos": "Consolidada en cáncer de próstata, endometriosis, miomas y pubertad precoz.", "evitar": "Embarazo. Efectos de la caída hormonal: sofocos, pérdida de masa ósea, alteraciones del estado de ánimo."}, "octreotida": {"oque": "Análogo sintético de la somatostatina con 8 aminoácidos, mucho más duradero que la hormona natural.", "age": ["Se une a los receptores de somatostatina e inhibe la liberación de GH, insulina, glucagón y otras hormonas.", "Reduce la secreción del tracto digestivo."], "hist": "Aprobada en la década de 1980; usada en acromegalia y tumores neuroendocrinos.", "estudos": "Reduce la GH/IGF-1 en la acromegalia y controla los síntomas de los tumores carcinoides.", "evitar": "Puede causar cálculos biliares y alterar la glucemia; requiere seguimiento."}, "abaloparatida": {"oque": "Análogo del péptido relacionado con la hormona paratiroidea (PTHrP), formador de hueso.", "age": ["Activa el receptor PTH1 de forma que favorece la formación ósea.", "Aumenta la densidad mineral ósea."], "hist": "Aprobada por la FDA en 2017 (Tymlos) para la osteoporosis posmenopáusica.", "estudos": "El estudio ACTIVE mostró una reducción de fracturas vertebrales y no vertebrales.", "evitar": "Pueden aparecer mareos y taquicardia al ponerse de pie; precaución con la hipercalcemia."}, "vosoritida": {"oque": "Análogo del péptido natriurético tipo C (CNP), para niños con acondroplasia.", "age": ["Activa el receptor NPR-B en las placas de crecimiento.", "Contrarresta parte del exceso de señal del FGFR3 que frena el crecimiento óseo."], "hist": "Aprobada por la FDA en 2021 (Voxzogo) como el primer medicamento específico para la acondroplasia.", "estudos": "Aumento modesto, pero sostenido, de la velocidad de crecimiento anual en niños.", "evitar": "Puede causar descenso de la presión arterial; uso restringido a pediatría especializada."}, "timosina-alfa-1": {"aviso": "Aprobación regional: este ítem no tiene aprobación de la FDA ni de la Anvisa. La etiqueta “Aprobado” se refiere a su uso en algunos países. Confírmelo directamente con el organismo regulador de su país.", "oque": "Péptido de 28 aminoácidos aislado originalmente del timo, glándula del sistema inmunitario.", "age": ["Modula células del sistema inmunitario, como los linfocitos T y las células dendríticas.", "Parece aumentar la respuesta inmunitaria a virus y vacunas."], "hist": "Usada en algunos países, como China e Italia, para la hepatitis B/C y como adyuvante; no está aprobada por la FDA para esta finalidad.", "estudos": "Los resultados son mixtos, con estudios de tamaño y calidad variables.", "evitar": "Precaución en personas que usan inmunosupresores o con trasplante. Compruebe siempre su situación en el organismo regulador de su país."}, "larazotida": {"oque": "Péptido de 8 aminoácidos que actúa en las uniones entre las células del intestino, estudiado en la enfermedad celíaca.", "age": ["Regula las uniones estrechas (tight junctions) del epitelio intestinal.", "Pretende disminuir el paso del gluten y otras moléculas hacia la pared del intestino."], "hist": "En desarrollo desde hace años; tuvo resultados mixtos en fase 3.", "estudos": "Algunos estudios mostraron menos síntomas en celíacos que seguían una dieta sin gluten, pero no hay aprobación.", "evitar": "No sustituye la dieta sin gluten. Aún en investigación."}, "teduglutida": {"oque": "Análogo del GLP-2 usado en el síndrome de intestino corto.", "age": ["Activa los receptores de GLP-2 en el intestino.", "Estimula el crecimiento de la mucosa y aumenta la absorción de líquidos y nutrientes."], "hist": "Aprobada por la FDA en 2012 (Gattex).", "estudos": "Redujo la necesidad de nutrición parenteral en pacientes con intestino corto.", "evitar": "Los pólipos y el cáncer del tracto gastrointestinal requieren evaluación previa y vigilancia colonoscópica."}, "apraglutida": {"oque": "Análogo de acción prolongada del GLP-2, estudiado en el síndrome de intestino corto.", "age": ["Activa los receptores de GLP-2, promoviendo el crecimiento y la función de la mucosa intestinal."], "hist": "Desarrollada para aplicación semanal; en fase 3.", "estudos": "Los estudios de fase 2 mostraron una menor necesidad de soporte parenteral.", "evitar": "No aprobada. Perfil de seguridad aún en evaluación."}, "zilucoplana": {"oque": "Péptido macrocíclico que bloquea el componente C5 del sistema del complemento.", "age": ["Se une al C5 e impide su escisión.", "Reduce la lesión provocada por el complemento en la unión neuromuscular en la miastenia gravis."], "hist": "Aprobada en 2023 (Zilbrysq) para la miastenia gravis generalizada con anticuerpos anti-AChR.", "estudos": "El estudio RAISE mostró mejoría en las escalas de actividades de la vida diaria.", "evitar": "Riesgo aumentado de infecciones por meningococo; requiere vacunación previa y vigilancia."}, "pegcetacoplana": {"oque": "Péptido cíclico unido a polietilenglicol que inhibe el componente C3 del complemento.", "age": ["Se une al C3 y bloquea la activación del complemento.", "Impide la destrucción de células sanguíneas en la hemoglobinuria paroxística nocturna (HPN)."], "hist": "Aprobada en 2021 (Empaveli) para la HPN y, después, en formulación intravítrea para la atrofia geográfica (Syfovre).", "estudos": "Superó a la terapia de comparación en la HPN; en la atrofia geográfica redujo la tasa de crecimiento de la lesión.", "evitar": "Riesgo de infecciones graves por bacterias encapsuladas; vacunas obligatorias."}, "elamipretida-ss-31": {"oque": "Tetrapéptido que se concentra en la membrana interna de la mitocondria.", "age": ["Se une a la cardiolipina, un lípido de la mitocondria.", "Ayuda a estabilizar la membrana y a mejorar la eficiencia de la producción de energía."], "hist": "Estudiada durante años en enfermedades mitocondriales; recibió aprobación acelerada de la FDA para el síndrome de Barth.", "estudos": "Los resultados en fuerza y función muscular dependieron del criterio de valoración; la aprobación se basó en marcadores.", "evitar": "Las reacciones en el lugar de la inyección son frecuentes. Uso solo en una indicación específica."}, "semax": {"aviso": "Semax no está aprobado por la FDA ni por la Anvisa. El uso clínico descrito es regional (Rusia) y la evidencia independiente es limitada. Confírmelo directamente con los organismos reguladores.", "oque": "Péptido sintético derivado de la ACTH (fragmento 4–10) con la adición de Pro-Gly-Pro, desarrollado en Rusia.", "age": ["Modula factores neurotróficos, como el BDNF.", "Puede influir en los neurotransmisores y en la respuesta al estrés."], "hist": "Se usa clínicamente en Rusia en accidente cerebrovascular y otras afecciones; no está aprobado por la FDA.", "estudos": "La mayoría de los estudios son rusos, con pocos ensayos independientes y diseños heterogéneos.", "evitar": "Evidencia internacional limitada. Consulte la situación regulatoria directamente con el organismo de su país."}, "bremelanotida-pt-141": {"oque": "Análogo de melanocortina que actúa en el sistema nervioso central, aprobado para el deseo sexual bajo en mujeres premenopáusicas.", "age": ["Activa receptores de melanocortina en el cerebro.", "Modula las vías del deseo sexual, no la circulación como los fármacos para la erección."], "hist": "Aprobada por la FDA en 2019 (Vyleesi).", "estudos": "Los estudios RECONNECT mostraron una mejora modesta del deseo en comparación con el placebo.", "evitar": "Puede elevar la presión arterial de forma transitoria; evitar en hipertensión no controlada o enfermedad cardiovascular. Las náuseas son frecuentes."}, "nisina": {"oque": "Péptido antimicrobiano (lantibiótico) producido por bacterias de la leche, usado como conservante alimentario.", "age": ["Se une al lípido II de la pared de las bacterias grampositivas.", "Forma poros en la membrana y bloquea la construcción de la pared celular."], "hist": "Se usa en la conservación de alimentos desde hace décadas; reconocida como segura (GRAS) para ese uso.", "estudos": "Hay muchos estudios en alimentos; las aplicaciones clínicas aún están en investigación.", "evitar": "Su uso como conservante está regulado; no es un medicamento aprobado para tratar infecciones."}, "glutationa": {"aviso": "Evidencia debatida: la absorción oral se considera baja, pero hay estudios con resultados distintos. Las infusiones y los usos estéticos no tienen un respaldo sólido. Busque orientación médica.", "oque": "Tripéptido formado por glutamato, cisteína y glicina; principal antioxidante producido dentro de las células.", "age": ["Neutraliza radicales libres y peróxidos.", "Participa en la desintoxicación de fármacos en el hígado.", "Mantiene otros antioxidantes, como la vitamina C, en su forma activa."], "hist": "Descubierta en 1921; hoy es objeto de suplementación y de uso clínico en contextos específicos (como el antídoto N-acetilcisteína, que aporta cisteína).", "estudos": "La absorción oral es baja y los resultados de suplementos e infusiones para aclarar la piel o desintoxicar no tienen evidencia sólida.", "evitar": "Las infusiones sin indicación médica no tienen una seguridad bien establecida. El asma puede empeorar con la forma inhalada."}, "testosterona": {"oque": "Hormona esteroidea (no es un péptido) producida principalmente en los testículos y, en menor cantidad, en los ovarios y las suprarrenales.", "age": ["Atraviesa la membrana de las células y se une al receptor de andrógenos.", "En algunos tejidos se convierte en dihidrotestosterona (más potente) o en estradiol.", "Estas señales mantienen la masa muscular, el hueso, la libido, el estado de ánimo y la producción de glóbulos rojos."], "hist": "Aislada en 1935 y sintetizada ese mismo año; es una de las bases de la endocrinología moderna. Existen geles, inyecciones de ésteres de acción prolongada y parches.", "estudos": "En hombres con hipogonadismo comprobado, mejora la libido, el ánimo de forma leve, la masa magra y la densidad ósea. El estudio TRAVERSE no mostró aumento de eventos cardiovasculares mayores en hombres de riesgo, pero señaló más fibrilación auricular y otros eventos.", "evitar": "Cáncer de próstata o de mama, policitemia, apnea del sueño grave no tratada, deseo de tener hijos (suprime la fertilidad). El uso estético o deportivo está prohibido por la AMA (WADA) y no es una indicación aprobada."}, "estradiol": {"oque": "Principal estrógeno, hormona esteroidea producida sobre todo en los ovarios antes de la menopausia.", "age": ["Se une a los receptores de estrógeno alfa y beta en el útero, la mama, el hueso, los vasos y el cerebro.", "Regula el ciclo menstrual, mantiene la mucosa vaginal y frena la pérdida de hueso.", "Actúa en el centro de la temperatura del cerebro, lo que explica su efecto sobre los sofocos."], "hist": "Aislado en 1930. La terapia hormonal de la menopausia se revisó a fondo tras el estudio WHI (2002), que cambió las recomendaciones de edad y duración.", "estudos": "Reduce los sofocos y la pérdida ósea. El riesgo de trombosis y de cáncer de mama depende de la vía (oral frente a cutánea), de la combinación con progestágeno, de la edad de inicio y del tiempo de uso.", "evitar": "Cáncer de mama o de endometrio hormonodependiente, trombosis previa, sangrado genital sin diagnóstico, enfermedad hepática grave, tabaquismo asociado a la vía oral a edades más avanzadas."}, "progesterona": {"oque": "Hormona esteroidea producida principalmente después de la ovulación y, durante la gestación, por la placenta.", "age": ["Se une a los receptores de progesterona en el útero, la mama y el cerebro.", "Transforma el endometrio, preparándolo para la implantación, y mantiene la gestación.", "Protege el endometrio del exceso de estrógeno en la terapia de la menopausia."], "hist": "Aislada en 1934. La forma micronizada, idéntica a la natural, permitió el uso oral y vaginal.", "estudos": "Reduce el riesgo de hiperplasia endometrial con estrógeno. En mujeres con cuello uterino corto, la progesterona vaginal reduce el parto prematuro; en el aborto de repetición el beneficio se limita a subgrupos.", "evitar": "Sangrado genital sin diagnóstico, cáncer de mama, trombosis activa, enfermedad hepática grave. Puede causar somnolencia, por eso suele tomarse por la noche."}, "hidrocortisona-cortisol": {"oque": "Forma farmacéutica del cortisol, el principal glucocorticoide producido por las suprarrenales.", "age": ["Se une al receptor de glucocorticoides, que modifica la expresión de muchos genes.", "Eleva la glucosa, moviliza grasa y proteínas y mantiene la presión arterial.", "Reduce la producción de señales inflamatorias y suprime la respuesta inmunitaria."], "hist": "La cortisona se usó por primera vez en la artritis en 1948 y valió el Nobel de 1950 a Kendall, Hench y Reichstein.", "estudos": "Es la base de la reposición en la enfermedad de Addison y en la hiperplasia suprarrenal congénita. Como antiinflamatorio tiene eficacia comprobada, pero el riesgo aumenta con la dosis y el tiempo.", "evitar": "El uso prolongado exige vigilar glucosa, presión, hueso e infecciones. La retirada debe ser gradual para evitar una crisis suprarrenal. Suspenderla sin orientación es peligroso."}, "dhea-prasterona": {"oque": "Hormona esteroidea producida en las suprarrenales, precursora de la testosterona y el estradiol; sus niveles disminuyen con la edad.", "age": ["Se convierte en los tejidos en andrógenos y estrógenos según la necesidad local.", "La forma vaginal actúa localmente sobre la mucosa, con poca absorción a la sangre."], "hist": "Popularizada como “hormona de la juventud” en los años 1990; la forma vaginal fue aprobada por la FDA en 2016 (Intrarosa).", "estudos": "La forma vaginal mejora la dispareunia posmenopáusica. Para el uso oral en personas sanas, los estudios no muestran un beneficio consistente y hay dudas sobre su seguridad.", "evitar": "Cánceres hormonodependientes, sangrado vaginal sin diagnóstico, gestación. Prohibida en competiciones deportivas por la AMA (WADA)."}, "levotiroxina-t4": {"oque": "Forma sintética de la T4, principal hormona producida por la tiroides.", "age": ["Se convierte en T3 en los tejidos, que se une a receptores en el núcleo de las células.", "Aumenta el gasto de energía, la frecuencia cardiaca y la producción de calor."], "hist": "La tiroxina se aisló en 1914 y se sintetizó en 1927. Es uno de los medicamentos más recetados del mundo.", "estudos": "Normaliza la TSH y mejora los síntomas del hipotiroidismo. En el hipotiroidismo subclínico leve en personas mayores, los ensayos no mostraron un beneficio claro.", "evitar": "Tomar en ayunas y separar del calcio, el hierro y los antiácidos. El exceso causa palpitaciones, pérdida ósea y arritmia. No sirve para adelgazar."}, "liotironina-t3": {"oque": "Forma activa de la hormona tiroidea, de acción rápida y corta.", "age": ["Se une directamente a los receptores nucleares de hormona tiroidea.", "Hace efecto en pocas horas, pero requiere dosis divididas para evitar picos."], "hist": "Se usa desde los años 1950 en situaciones en las que se busca un efecto rápido o reversible.", "estudos": "La combinación T4 + T3 no mostró una ventaja consistente en la mayoría de los ensayos; puede considerarse en casos seleccionados por un especialista.", "evitar": "Las personas con cardiopatía y las mayores requieren precaución. El uso para adelgazar es peligroso y no está aprobado."}, "melatonina": {"oque": "Hormona producida por la noche por la glándula pineal, que ayuda a regular el ritmo de sueño y vigilia.", "age": ["Se une a los receptores MT1 y MT2, sobre todo en el núcleo supraquiasmático del hipotálamo.", "Señala la oscuridad y adelanta o retrasa el reloj biológico según la hora a la que se toma."], "hist": "Descubierta en 1958. En EE. UU. se vende como suplemento, mientras que en Europa existe un medicamento de liberación prolongada (Circadin).", "estudos": "Reduce ligeramente el tiempo para conciliar el sueño y ayuda en el retraso de fase del sueño y el jet lag. El efecto en el insomnio común es modesto.", "evitar": "Precaución con anticoagulantes y sedantes. Las etiquetas de los suplementos pueden diferir del contenido real; en niños, solo con orientación médica."}, "gonadotrofina-corionica-hcg": {"oque": "Hormona producida por la placenta durante la gestación; es una glucoproteína, no un péptido corto, que actúa como la LH.", "age": ["Se une al receptor de LH/hCG en las células de Leydig de los testículos y en los ovarios.", "Estimula la producción de testosterona o la ovulación, según el contexto."], "hist": "Se identificó en la orina de embarazadas en los años 1920, base de las primeras pruebas de embarazo.", "estudos": "Eficaz para inducir la ovulación y en el hipogonadismo secundario. Los ensayos mostraron que no ayuda a adelgazar.", "evitar": "Cánceres sensibles a hormonas, gestación (fuera de protocolos de fertilidad). Prohibida por la AMA (WADA) en hombres."}, "glucagon": {"oque": "Hormona peptídica de 29 aminoácidos producida por las células alfa del páncreas.", "age": ["Se une al receptor de glucagón en el hígado.", "Estimula la degradación del glucógeno y la producción de glucosa, elevando la glucemia en minutos."], "hist": "Descubierto en 1923. Hoy existen formas listas para usar y nasales, que facilitan el auxilio por personas legas.", "estudos": "Revierte la hipoglucemia grave con eficacia demostrada en ensayos; el efecto depende de que haya glucógeno en el hígado.", "evitar": "Menos eficaz en ayuno prolongado, alcoholismo e insuficiencia suprarrenal. Puede causar náuseas y vómitos; coloque al paciente de lado."}, "calcitonina": {"oque": "Hormona de 32 aminoácidos producida por las células C de la tiroides.", "age": ["Se une al receptor de calcitonina en los osteoclastos.", "Reduce la resorción ósea y la liberación de calcio a la sangre."], "hist": "Descubierta en 1962. La calcitonina de salmón es más potente que la humana.", "estudos": "Útil en la hipercalcemia aguda y la enfermedad de Paget. En la osteoporosis, el beneficio en fracturas es pequeño y hay una alerta por un posible aumento de cáncer con el uso prolongado.", "evitar": "Hipocalcemia y alergia a proteínas de pescado. La forma nasal se retiró en algunos mercados."}, "desmopressina": {"oque": "Análogo sintético de la vasopresina, con 9 aminoácidos y menor efecto sobre la presión arterial.", "age": ["Se une al receptor V2 en los túbulos colectores de los riñones.", "Aumenta la reabsorción de agua y reduce el volumen de orina.", "También eleva el factor VIII y el factor de von Willebrand, lo que ayuda a la coagulación."], "hist": "Desarrollada en los años 1960 y usada desde entonces para la diabetes insípida y la enuresis.", "estudos": "Reduce las noches con escapes en niños y el número de despertares nocturnos en adultos con nicturia.", "evitar": "Riesgo de hiponatremia grave, sobre todo en personas mayores y con exceso de líquidos. Evitar con ciertos diuréticos y antiinflamatorios."}, "metreleptina": {"oque": "Análogo de la leptina, proteína producida por el tejido adiposo que informa al cerebro sobre las reservas de energía.", "age": ["Se une al receptor de leptina en el hipotálamo y en otros tejidos.", "En personas con lipodistrofia y leptina muy baja, reduce el hambre y mejora la sensibilidad a la insulina y la grasa del hígado."], "hist": "Aprobada por la FDA en 2014 (Myalept) dentro de un programa restringido de seguridad.", "estudos": "Reduce la HbA1c y los triglicéridos en pacientes con lipodistrofia generalizada. No es eficaz en la obesidad común, en la que la leptina suele estar alta.", "evitar": "Advertencia de recuadro negro por anticuerpos neutralizantes y linfoma de células T. Puede requerir reducir la dosis de insulina."}, "vitamina-d3-colecalciferol": {"oque": "Vitamina liposoluble que la piel produce con la luz solar y que también procede de la dieta; funciona como una hormona.", "age": ["En el hígado se convierte en 25-hidroxivitamina D y, en los riñones, en calcitriol (forma activa).", "El calcitriol se une al receptor de vitamina D y aumenta la absorción de calcio en el intestino.", "También participa en las células musculares y en el sistema inmunitario."], "hist": "Su relación con el raquitismo se aclaró en los años 1920. La fortificación de la leche y otros alimentos redujo el raquitismo.", "estudos": "Previene el raquitismo y la osteomalacia. En ensayos grandes (VITAL, D2d), la suplementación en personas sin deficiencia no previno de forma significativa el cáncer, la enfermedad cardiaca ni la diabetes.", "evitar": "Evitar dosis muy altas sin análisis: hipercalcemia, cálculos y lesión renal. Las personas con sarcoidosis o hiperparatiroidismo necesitan seguimiento."}, "vitamina-b12-cobalamina": {"oque": "Vitamina hidrosoluble que contiene cobalto; solo la producen microorganismos y procede de alimentos de origen animal.", "age": ["Para absorberse necesita el factor intrínseco, producido en el estómago.", "Actúa en dos enzimas: una en la síntesis de metionina (con el folato) y otra en el metabolismo de los ácidos grasos.", "Sin ella se producen anemia megaloblástica y lesión de los nervios."], "hist": "La anemia perniciosa era mortal hasta el descubrimiento del tratamiento con hígado, que mereció el Nobel de 1934.", "estudos": "La reposición trata la anemia y la neuropatía. En personas sin deficiencia, la suplementación no mejoró la energía ni la memoria de forma consistente.", "evitar": "La metformina, los inhibidores de la bomba de protones, la cirugía bariátrica y la dieta vegana aumentan el riesgo de deficiencia. Las dosis orales altas funcionan incluso sin factor intrínseco."}, "vitamina-c-acido-ascorbico": {"oque": "Vitamina hidrosoluble que los humanos no producen y deben obtener de frutas y verduras.", "age": ["Es cofactor de enzimas que forman colágeno.", "Neutraliza radicales libres y regenera la vitamina E.", "Aumenta la absorción del hierro de origen vegetal."], "hist": "El escorbuto de los marineros fue tratado con cítricos por James Lind en 1747, en uno de los primeros ensayos clínicos.", "estudos": "Previene el escorbuto. En los resfriados, reduce un poco la duración en quienes la toman con regularidad, sin prevenir la enfermedad en la mayoría de las personas.", "evitar": "Las dosis altas favorecen los cálculos de oxalato y la diarrea, interfieren con los glucómetros y aumentan la absorción de hierro en personas con hemocromatosis."}, "vitamina-b6-piridoxina": {"oque": "Vitamina hidrosoluble que da origen al piridoxal fosfato, cofactor de más de un centenar de enzimas.", "age": ["Participa en la conversión de aminoácidos y en la síntesis de neurotransmisores como la serotonina y el GABA.", "También es necesaria para formar hemoglobina."], "hist": "Identificada en los años 1930; la deficiencia es rara y suele estar relacionada con medicamentos o alcoholismo.", "estudos": "Puede aliviar las náuseas del embarazo, combinada o no con doxilamina. La evidencia para el síndrome premenstrual y la depresión es débil.", "evitar": "Las dosis altas y prolongadas (más de ~100 mg/día) causan neuropatía periférica. Atención a varios suplementos que suman B6."}, "folato-vitamina-b9": {"oque": "Vitamina del complejo B; el ácido fólico es la forma sintética estable, usada en suplementos y en la fortificación de harinas.", "age": ["Aporta unidades de un carbono para formar las bases del ADN.", "Junto con la B12, recicla la homocisteína en metionina."], "hist": "Su relación con los defectos del tubo neural llevó a la fortificación obligatoria de harinas en muchos países a partir de los años 1990.", "estudos": "El ácido fólico antes de la concepción reduce los defectos del tubo neural en cerca de un 70%. No redujo de forma consistente las enfermedades cardiovasculares.", "evitar": "Las dosis altas pueden enmascarar la deficiencia de B12. Interactúa con metotrexato, fenitoína y otros fármacos."}, "vitamina-k2-menaquinona": {"oque": "Grupo de vitaminas liposolubles (MK-4 a MK-13) producidas por bacterias y presentes en alimentos fermentados y productos animales.", "age": ["Actúa como cofactor de la carboxilasa que activa las proteínas dependientes de vitamina K.", "Estas proteínas incluyen factores de la coagulación, la osteocalcina (hueso) y la proteína Gla de la matriz (arterias)."], "hist": "La vitamina K se descubrió en 1929 por su acción en la coagulación (letra K del alemán Koagulation).", "estudos": "Esencial para la coagulación. Para el hueso y la calcificación vascular, los ensayos con K2 muestran resultados mixtos y poblaciones heterogéneas.", "evitar": "Quien usa warfarina debe mantener una ingesta estable y avisar al médico antes de usar suplementos."}, "vitamina-a-retinol": {"oque": "Vitamina liposoluble presente en el hígado, los huevos y los lácteos; las plantas aportan carotenoides que el cuerpo convierte en vitamina A.", "age": ["El retinal forma parte de la rodopsina, pigmento esencial para la visión con poca luz.", "El ácido retinoico se une a los receptores RAR y RXR y regula la diferenciación de las células de la piel y las mucosas.", "También es importante para la inmunidad."], "hist": "Fue una de las primeras vitaminas identificadas (1913). La deficiencia sigue siendo una causa importante de ceguera infantil en el mundo.", "estudos": "La suplementación en poblaciones con deficiencia reduce la mortalidad infantil. En fumadores, el betacaroteno aumentó el riesgo de cáncer de pulmón en los estudios ATBC y CARET.", "evitar": "El exceso (hipervitaminosis A) daña el hígado y los huesos y, en el embarazo, causa malformaciones. Los retinoides para la piel no deben sumarse a los suplementos."}, "vitamina-e-tocoferol": {"oque": "Grupo de ocho compuestos liposolubles; el alfa-tocoferol es la forma más activa en el cuerpo humano.", "age": ["Interrumpe la oxidación de los lípidos en las membranas celulares.", "Depende de otros antioxidantes, como la vitamina C, para volver a su forma activa."], "hist": "Descubierta en 1922 por su importancia en la reproducción de ratas. El interés como antioxidante creció en los años 1990.", "estudos": "Ensayos como HOPE, SELECT y ATBC no mostraron prevención de enfermedad cardiaca ni de cáncer. El SELECT sugirió un aumento del riesgo de cáncer de próstata.", "evitar": "Evitar dosis altas con anticoagulantes o antes de cirugías. Las personas bien nutridas rara vez necesitan suplementarla."}, "niacina-vitamina-b3": {"oque": "Vitamina del complejo B (ácido nicotínico y nicotinamida) que el cuerpo usa para fabricar NAD+.", "age": ["Se convierte en NAD+ y NADP+, que transportan electrones en reacciones de producción de energía.", "En dosis farmacológicas altas, reduce el LDL y los triglicéridos y aumenta el HDL."], "hist": "Se identificó como cura de la pelagra en 1937. En dosis altas fue una de las primeras terapias para la dislipidemia.", "estudos": "Los estudios AIM-HIGH y HPS2-THRIVE no mostraron un beneficio cardiovascular adicional en personas que ya tomaban estatinas, y hubo más efectos adversos.", "evitar": "Las dosis altas causan rubor, picor, alteraciones hepáticas y elevación de la glucosa y del ácido úrico. Su uso exige seguimiento."}, "nad": {"oque": "Dinucleótido de nicotinamida y adenina, coenzima presente en todas las células vivas; no es un péptido.", "age": ["Acepta y dona electrones en reacciones de producción de energía en la mitocondria.", "Es consumido por las sirtuinas (reparación y regulación génica) y las PARP (reparación del ADN).", "Los niveles en los tejidos disminuyen con la edad en modelos animales, lo que motiva el interés por su reposición."], "hist": "Descubierto en 1906 por Harden y Young. El interés en el tema para el envejecimiento creció tras los estudios de sirtuinas en los años 2000.", "estudos": "En animales, aumentar el NAD+ mejoró la función muscular y metabólica. En humanos, los datos con NAD+ administrado directamente son escasos y, en general, sin desenlaces clínicos sólidos.", "evitar": "Las infusiones intravenosas rápidas causan náuseas, opresión en el pecho y malestar. Existe una preocupación teórica sobre su uso en cáncer. No es un medicamento aprobado."}, "nmn-mononucleotideo-de-nicotinamida": {"oque": "Nucleótido que es precursor directo del NAD+ y existe en pequeñas cantidades en alimentos como el brócoli y el aguacate.", "age": ["Se convierte en NAD+ mediante una enzima llamada NMNAT.", "El mecanismo exacto de entrada en las células humanas aún se debate."], "hist": "Atrajo la atención tras estudios en ratones envejecidos. La situación regulatoria en EE. UU. ha cambiado más de una vez.", "estudos": "Ensayos pequeños en humanos mostraron aumento del NAD+ en sangre y, en algunos, una leve mejoría de la fuerza o de la sensibilidad a la insulina, pero con resultados inconsistentes.", "evitar": "Faltan datos a largo plazo; evitar en el embarazo y en cáncer activo sin orientación profesional. Verifique el origen y la pureza de los productos."}, "nicotinamida-ribosideo-nr": {"oque": "Forma de vitamina B3 que es precursora del NAD+ y fue identificada en la leche.", "age": ["Se absorbe y se convierte en NMN y después en NAD+.", "Aumenta el NAD+ en la sangre y en los tejidos en humanos de forma dependiente de la dosis."], "hist": "Reconocida como precursora del NAD+ en 2004 por Charles Brenner. Se comercializa como suplemento en varios países.", "estudos": "Los ensayos mostraron elevación del NAD+ con efectos clínicos modestos en la presión arterial, la rigidez arterial y otros desenlaces; en el Parkinson y en enfermedades musculares, los resultados aún son iniciales.", "evitar": "En general bien tolerada en estudios cortos, con náuseas y fatiga leves. Evitar en el embarazo y en cáncer activo sin orientación."}, "l-carnitina": {"oque": "Compuesto producido por el organismo y obtenido de la alimentación. La levocarnitina medicinal trata deficiencias específicas, no las afirmaciones generales de los suplementos.", "age": ["Participa en el transporte de ciertos ácidos grasos hacia la mitocondria.", "Esos ácidos grasos pueden usarse para producir energía.", "El organismo también obtiene carnitina de los alimentos, sobre todo de origen animal."], "hist": "Identificada a principios del siglo XX, su papel metabólico se aclaró más tarde. La levocarnitina tiene uso medicinal en deficiencias específicas.", "estudos": "La reposición está indicada en la deficiencia diagnosticada. Los beneficios de los suplementos en personas sin deficiencia son inciertos.", "evitar": "La enfermedad renal y los medicamentos exigen una evaluación individual; puede causar molestias gastrointestinales."}, "acetil-l-carnitina": {"oque": "Forma acetilada de la carnitina presente en los tejidos y estudiada en el metabolismo y la función nerviosa. La investigación no demuestra eficacia general de los suplementos.", "age": ["Forma parte del conjunto de formas de carnitina del organismo.", "La carnitina participa en el transporte de ácidos grasos a la mitocondria.", "Se investigan efectos adicionales en el sistema nervioso, sin beneficio garantizado."], "hist": "Estudiada en ensayos para neuropatía y algunas condiciones cognitivas. Las indicaciones y las formulaciones varían entre investigaciones.", "estudos": "Los resultados clínicos varían según la condición y la calidad de los estudios. No hay un efecto preventivo o cognitivo amplio establecido.", "evitar": "Puede causar síntomas gastrointestinales, agitación u olor corporal; los datos de seguridad son limitados."}, "acido-alfa-lipoico": {"oque": "Cofactor de enzimas del metabolismo energético mitocondrial y participante en reacciones redox. Los medicamentos usados en algunos países son distintos de los suplementos.", "age": ["Participa en complejos enzimáticos que procesan nutrientes para generar energía.", "Su forma oxidada y reducida participa en reacciones redox.", "Se estudia clínicamente sobre todo para la neuropatía diabética."], "hist": "El ácido tióctico se usa como medicamento en algunos países europeos. También se vende como suplemento de composición variable.", "estudos": "Los ensayos en neuropatía diabética son heterogéneos y dependen de la formulación. No hay un beneficio general para la longevidad establecido.", "evitar": "Puede reducir la glucosa; el tratamiento de la diabetes requiere evaluación profesional."}, "n-acetilcisteina-nac": {"oque": "Forma acetilada de la cisteína y precursora del glutatión. Los medicamentos tienen indicaciones específicas, incluida la intoxicación por paracetamol y el uso mucolítico.", "age": ["Aporta cisteína que puede usarse para sintetizar glutatión.", "El glutatión participa en las defensas redox celulares.", "En presentación mucolítica, puede reducir la viscosidad de las secreciones."], "hist": "La acetilcisteína se usa como antídoto de la intoxicación por paracetamol y en contextos respiratorios. La aprobación depende de la presentación y del país.", "estudos": "Existe evidencia para indicaciones farmacéuticas específicas. Los resultados para otros usos varían.", "evitar": "Puede causar hipersensibilidad y síntomas digestivos; puede intensificar los efectos de la nitroglicerina."}, "coenzima-q10": {"oque": "Compuesto celular que participa en la cadena respiratoria mitocondrial y en procesos redox. La suplementación se estudia en diversas condiciones.", "age": ["Participa en la transferencia de electrones en la cadena mitocondrial.", "Contribuye a la generación de ATP.", "También participa en procesos antioxidantes celulares."], "hist": "La coenzima Q10 fue identificada como componente mitocondrial a mediados del siglo XX. Su suplementación se investiga en distintas condiciones.", "estudos": "Los ensayos varían según la condición y no establecen un beneficio general. Algunas indicaciones siguen siendo inciertas.", "evitar": "Puede causar síntomas digestivos e interactuar con la warfarina; no sustituye el tratamiento prescrito."}, "creatina": {"oque": "Molécula sintetizada por el cuerpo y obtenida de la dieta, almacenada en parte como fosfocreatina. Ayuda a amortiguar la energía celular de uso rápido.", "age": ["La creatina puede recibir un grupo fosfato y formar fosfocreatina.", "La fosfocreatina ayuda a regenerar ATP en demandas energéticas rápidas.", "Los músculos almacenan gran parte de la creatina corporal."], "hist": "La creatina fue aislada en el siglo XIX y ampliamente estudiada en fisiología del ejercicio. Los suplementos varían en forma y calidad.", "estudos": "Hay evidencia para algunos desenlaces de rendimiento y composición corporal. Los usos clínicos y otras poblaciones siguen en estudio.", "evitar": "Puede alterar la creatinina de laboratorio; la enfermedad renal requiere interpretación clínica."}, "taurina": {"oque": "Compuesto sulfurado abundante en los tejidos, no incorporado a las proteínas como un aminoácido común. Participa en el equilibrio osmótico, las sales biliares y la señalización.", "age": ["Ayuda a regular el equilibrio de agua e iones celulares.", "Participa en la conjugación de ácidos biliares.", "También actúa en la señalización neural y muscular."], "hist": "La taurina fue aislada en el siglo XIX y estudiada en nutrición y fisiología. Los efectos de la suplementación varían según el contexto.", "estudos": "Los estudios clínicos son limitados para muchas afirmaciones. No hay eficacia terapéutica amplia establecida.", "evitar": "Los datos sobre suplementación prolongada y en grupos clínicos son limitados."}, "glicina": {"oque": "Aminoácido usado en la formación de proteínas, creatina y glutatión. En el sistema nervioso, actúa como neurotransmisor inhibidor en algunas regiones y como coagonista de NMDA.", "age": ["Se incorpora a proteínas y moléculas metabólicas.", "Puede actuar sobre receptores de glicina en el sistema nervioso.", "También funciona como coagonista de NMDA en sitios específicos."], "hist": "La glicina se conoce como aminoácido desde el siglo XIX. Su papel como neurotransmisor se caracterizó posteriormente.", "estudos": "Estudios pequeños sobre el sueño y el metabolismo no establecen un tratamiento eficaz. La ingesta y la producción corporal forman parte del metabolismo normal.", "evitar": "Puede causar molestias gastrointestinales; los datos de uso prolongado son limitados."}, "omega-3-epa-dha": {"oque": "EPA y DHA son ácidos grasos que se encuentran sobre todo en pescados y en algunos productos de algas. Los medicamentos purificados tienen indicaciones distintas de las de los suplementos comunes.", "age": ["EPA y DHA se incorporan a las membranas celulares.", "Pueden servir como precursores de mediadores lipídicos.", "La cantidad varía entre alimentos, suplementos y medicamentos."], "hist": "Los estudios de aceites marinos llevaron a formulaciones farmacéuticas de omega-3. La FDA aprobó productos específicos para indicaciones delimitadas.", "estudos": "La evidencia depende del producto, la población y el desenlace. Un medicamento no demuestra eficacia equivalente para cualquier suplemento.", "evitar": "Las dosis farmacológicas pueden afectar el sangrado o la fibrilación auricular en algunos grupos."}, "citicolina": {"oque": "También llamada CDP-colina, es un intermediario del metabolismo de la colina y de los fosfolípidos. Se estudia en condiciones neurológicas sin aprobación universal para esos usos.", "age": ["Tras la ingestión, aporta colina y citidina al metabolismo.", "Esos componentes participan en la síntesis de fosfolípidos de membrana.", "La colina también es precursora de la acetilcolina."], "hist": "La citicolina fue desarrollada e investigada en enfermedades neurológicas. La disponibilidad y la situación regulatoria varían según el país.", "estudos": "Los ensayos en ictus y cognición tuvieron resultados inconsistentes. No hay un beneficio general confirmado.", "evitar": "Puede causar cefalea, síntomas digestivos o insomnio; la seguridad depende del contexto."}, "ergotioneina": {"oque": "Compuesto con azufre que se encuentra en algunos alimentos, sobre todo en los hongos, y que una proteína específica transporta a los tejidos. Su papel como suplemento está en investigación.", "age": ["Se obtiene principalmente de la alimentación.", "Un transportador celular específico facilita su entrada en algunos tejidos.", "Se investigan sus propiedades redox, sin que se haya comprobado la prevención de enfermedades."], "hist": "La ergotioneína fue aislada de hongos a principios del siglo XX. Las investigaciones examinan su transporte y sus funciones biológicas.", "estudos": "Los estudios clínicos son iniciales y no demuestran beneficio preventivo ni de longevidad.", "evitar": "No se ha definido la seguridad de la suplementación prolongada."}, "resveratrol": {"oque": "Polifenol presente en algunas plantas, incluidas las uvas. La actividad en células y animales no prueba un beneficio clínico ni un aumento de la longevidad.", "age": ["Se absorbe y se metaboliza rápidamente tras la ingestión.", "En modelos experimentales influye en diversas vías celulares.", "La relevancia de esos cambios para la salud humana sigue siendo incierta."], "hist": "El resveratrol ganó atención por estudios experimentales sobre envejecimiento y metabolismo. Los ensayos en humanos evaluaron desenlaces diversos.", "estudos": "Los estudios en humanos son heterogéneos y no prueban la prevención de enfermedades ni la prolongación de la vida.", "evitar": "Puede interactuar con medicamentos, incluidos los anticoagulantes; la seguridad de las dosis concentradas es incierta."}, "pterostilbeno": {"oque": "Polifenol relacionado con el resveratrol, presente en pequeñas cantidades en algunas plantas. La mayoría de las afirmaciones proviene de investigación preclínica.", "age": ["Se investiga por sus propiedades redox en modelos.", "Puede afectar la señalización metabólica en células y animales.", "No se sabe si esos efectos generan un beneficio clínico en personas."], "hist": "El pterostilbeno se estudió inicialmente en laboratorio y en animales. Los datos clínicos disponibles son escasos.", "estudos": "No hay evidencia de beneficio para la longevidad; los estudios en humanos son insuficientes.", "evitar": "La seguridad prolongada y las interacciones de los suplementos concentrados son poco conocidas."}, "urolitina-a": {"oque": "Metabolito formado por algunas microbiotas intestinales a partir de compuestos de ciertos alimentos. La capacidad de producirla varía entre las personas.", "age": ["Algunos alimentos aportan precursores como los elagitaninos.", "Ciertas microbiotas transforman esos precursores en urolitinas.", "La urolitina A se estudia por una posible relación con la mitofagia, sin efecto garantizado."], "hist": "Fue caracterizada como metabolito alimentario y estudiada en ensayos de seguridad y función muscular.", "estudos": "Los ensayos iniciales no demuestran longevidad ni beneficio clínico duradero.", "evitar": "La producción intestinal varía; los datos de suplementación prolongada son limitados."}, "espermidina": {"oque": "Poliamina producida por las células y presente en los alimentos. Participa en procesos celulares y se investiga por una posible relación con la autofagia.", "age": ["Participa en la regulación del crecimiento y de la función celular.", "La autofagia es un proceso de reciclaje de componentes celulares.", "La asociación mecanística no prueba un beneficio de la suplementación."], "hist": "La espermidina se estudia en biología celular desde hace décadas y ganó atención en la investigación sobre el envejecimiento.", "estudos": "Las observaciones poblacionales y los estudios iniciales no demuestran prolongación de la vida mediante suplementación.", "evitar": "Los efectos del uso prolongado y en enfermedades crónicas son poco conocidos."}, "pqq-pirroloquinolina-quinona": {"oque": "El PQQ es un compuesto redox estudiado en células y animales. Las afirmaciones sobre biogénesis mitocondrial no equivalen a un beneficio clínico demostrado.", "age": ["Se investiga por participar en reacciones redox en modelos.", "Los estudios preclínicos examinan la señalización mitocondrial.", "La importancia de esos efectos en humanos sigue siendo incierta."], "hist": "El PQQ fue caracterizado como cofactor microbiano y posteriormente evaluado en estudios nutricionales.", "estudos": "Los ensayos en humanos son pequeños y no prueban la prevención de enfermedades ni la longevidad.", "evitar": "La seguridad de la suplementación prolongada está poco caracterizada."}, "fisetina": {"oque": "Flavonoide presente en algunos alimentos vegetales y estudiado por sus efectos antioxidantes y sobre las células senescentes. No se ha establecido una actividad senolítica clínica.", "age": ["Se encuentra en los alimentos en cantidades variables.", "En modelos, puede alterar señales celulares de estrés y senescencia.", "Los hallazgos preclínicos no demuestran la eliminación segura de células senescentes en humanos."], "hist": "La fisetina se estudia como flavonoide y en investigación preclínica sobre la senescencia celular.", "estudos": "La evidencia senolítica es principalmente de laboratorio y animal; los estudios en humanos no confirman beneficio.", "evitar": "La seguridad y las interacciones de los suplementos concentrados son inciertas."}, "quercetina": {"oque": "Flavonoide presente en frutas, verduras y otras plantas. La actividad antioxidante en modelos no significa eficacia contra enfermedades en humanos.", "age": ["Se obtiene de la alimentación y también se vende en suplementos.", "En modelos experimentales, interactúa con diversas vías celulares.", "La absorción depende de la forma química y de la matriz alimentaria."], "hist": "La quercetina se conoce como pigmento vegetal y se investiga en estudios nutricionales y clínicos.", "estudos": "Los ensayos pequeños y heterogéneos no demuestran un beneficio preventivo amplio ni la prolongación de la vida.", "evitar": "Puede interactuar con medicamentos; la seguridad prolongada de las dosis concentradas es incierta."}, "slu-pp-332": {"oque": "Molécula experimental descrita como agonista de los receptores ERR, que regulan genes metabólicos. Los hallazgos preclínicos no demuestran que sustituya al ejercicio.", "age": ["La molécula activa receptores ERR en modelos experimentales.", "Los ERR regulan programas de expresión génica relacionados con el metabolismo.", "Los resultados en animales no establecen eficacia ni seguridad en humanos."], "hist": "SLU-PP-332 fue descrito en investigación preclínica sobre los receptores ERR y el metabolismo. No existe un medicamento aprobado con este compuesto.", "estudos": "Evidencia preclínica; no se ha demostrado beneficio clínico en humanos.", "evitar": "Se desconocen la seguridad en humanos, los efectos a largo plazo y la composición de los productos de investigación."}, "5-amino-1mq": {"oque": "Molécula experimental investigada como inhibidor de la NNMT, una enzima del metabolismo de la nicotinamida. No es un mimético del ejercicio comprobado.", "age": ["En estudios preclínicos, inhibe la NNMT.", "Esta inhibición puede alterar vías metabólicas en modelos.", "Los resultados no prueban pérdida de peso, mejora física ni seguridad en humanos."], "hist": "El 5-amino-1MQ se estudió en modelos celulares y animales del metabolismo. No existe un medicamento aprobado con este compuesto.", "estudos": "Solo evidencia preclínica; no se han establecido la eficacia ni la seguridad clínicas.", "evitar": "Los datos en humanos son insuficientes; se desconoce la calidad de los productos de investigación."}, "magnesio": {"oque": "Mineral esencial presente en los huesos y en las células. Participa en cientos de reacciones enzimáticas, en la producción de energía y en la función de los nervios y los músculos.", "age": ["Actúa como cofactor de enzimas que usan ATP.", "Ayuda a regular la contracción muscular y la transmisión nerviosa.", "Contribuye a la estructura ósea y al equilibrio de otros electrolitos."], "hist": "La importancia del magnesio en la nutrición y en la función neuromuscular se conoce desde hace décadas. Los suplementos y las sales medicinales difieren en absorción y tolerabilidad.", "estudos": "La reposición corrige la deficiencia y está indicada en contextos clínicos definidos. Para calambres, sueño o prevención de enfermedades en personas sin deficiencia, los resultados varían y no justifican promesas generales.", "evitar": "En la enfermedad renal, la acumulación puede ser peligrosa. Las dosis de suplemento pueden causar diarrea e interferir en la absorción de algunos antibióticos y de la levotiroxina."}, "zinco": {"oque": "Mineral esencial presente en muchas enzimas y proteínas. Es necesario para la inmunidad, el crecimiento, la cicatrización y la síntesis de ADN.", "age": ["Forma parte de la estructura de proteínas que regulan la expresión de los genes.", "Es necesario para la división celular y el funcionamiento de las células inmunes.", "Contribuye al gusto, al olfato y a la reparación de los tejidos."], "hist": "La deficiencia de zinc se reconoció como problema nutricional humano en el siglo XX. Hoy el mineral se obtiene de alimentos, suplementos y medicamentos específicos.", "estudos": "La reposición es útil en la deficiencia confirmada o probable y en situaciones clínicas seleccionadas. El uso preventivo amplio o para tratar resfriados tiene un beneficio variable y depende del contexto y de la formulación.", "evitar": "El uso excesivo y prolongado puede causar deficiencia de cobre, anemia y alteraciones neurológicas. Puede reducir la absorción de algunos antibióticos; informe al profesional sobre los suplementos."}, "selenio": {"oque": "Mineral esencial incorporado a las selenoproteínas. Algunas de estas proteínas protegen componentes celulares de la oxidación y participan en el metabolismo de las hormonas tiroideas.", "age": ["Se incorpora como selenocisteína a enzimas antioxidantes, como las glutatión peroxidasas.", "Ayuda a controlar reacciones de oxidación y reducción en las células.", "Participa en enzimas que transforman las hormonas tiroideas."], "hist": "El selenio se reconoció como nutriente esencial tras identificarse sus funciones en enzimas humanas. Tanto la deficiencia como el exceso pueden causar problemas.", "estudos": "Corregir la deficiencia es importante. En personas con ingesta adecuada, los ensayos no demuestran un beneficio consistente de la suplementación para prevenir el cáncer o la enfermedad cardiovascular.", "evitar": "El exceso crónico puede causar selenosis, con alteraciones del cabello, las uñas, el aliento y el sistema nervioso. La concentración en alimentos y productos varía."}, "ferro": {"oque": "Mineral esencial que forma parte de la hemoglobina y la mioglobina y participa en enzimas. El organismo recicla gran parte del hierro de los glóbulos rojos envejecidos.", "age": ["La hemoglobina usa hierro para transportar oxígeno en la sangre.", "La mioglobina almacena oxígeno en el músculo.", "Las enzimas con hierro participan en la respiración celular y en la producción de energía."], "hist": "La relación entre la falta de hierro y la anemia se conoce desde la medicina antigua. La deficiencia puede deberse a pérdidas de sangre, mayor necesidad o absorción inadecuada.", "estudos": "El tratamiento de la deficiencia y de la anemia ferropénica mejora las reservas y la hemoglobina. Debe investigarse la causa de la deficiencia; el hierro no trata la anemia de cualquier origen.", "evitar": "No lo use sin una evaluación de deficiencia, pues la sobrecarga puede dañar el hígado, el corazón y otros órganos. Mantenga los productos con hierro fuera del alcance de los niños; la ingestión accidental puede ser mortal."}, "tiamina-vitamina-b1": {"oque": "La tiamina, o vitamina B1, es una vitamina hidrosoluble necesaria para el metabolismo energético y para el funcionamiento de los nervios y los músculos.", "age": ["Se convierte en pirofosfato de tiamina, su forma coenzimática activa.", "Ayuda a las enzimas a metabolizar la glucosa y ciertos aminoácidos.", "Sostiene especialmente los tejidos con alta demanda energética, como el cerebro y el corazón."], "hist": "La deficiencia de tiamina ayudó a identificar la causa del beriberi. Su importancia clínica se reconoce especialmente en la desnutrición, el alcoholismo y algunas condiciones de malabsorción.", "estudos": "La reposición previene o trata la deficiencia y debe ser rápida cuando se sospecha encefalopatía de Wernicke. No hay evidencia de que aumente la energía o el rendimiento en personas con un estado nutricional adecuado.", "evitar": "La vía inyectable puede causar raramente una reacción alérgica grave y requiere un entorno apropiado. Las situaciones de riesgo y los síntomas neurológicos necesitan evaluación médica."}, "riboflavina-vitamina-b2": {"oque": "La riboflavina, o vitamina B2, es precursora de FMN y FAD, coenzimas utilizadas en reacciones de producción de energía.", "age": ["Se convierte en FMN y FAD dentro de las células.", "Estas coenzimas participan en reacciones de oxidorreducción.", "También contribuye al metabolismo de otras vitaminas y al mantenimiento de los tejidos."], "hist": "La riboflavina fue identificada a principios del siglo XX y su deficiencia se asoció a alteraciones de la piel y las mucosas. Se obtiene de los alimentos y de la fortificación.", "estudos": "La suplementación trata la deficiencia. Los ensayos de prevención de la migraña sugieren beneficio en algunos pacientes, pero la respuesta varía y no significa que sea un tratamiento universal.", "evitar": "En general es bien tolerada; la orina amarillo intenso tras la ingesta es esperable. Informe al laboratorio sobre los suplementos, ya que algunos análisis pueden verse afectados."}, "biotina-vitamina-b7": {"oque": "La biotina, o vitamina B7, es una vitamina hidrosoluble que actúa como cofactor de enzimas metabólicas.", "age": ["Se une a carboxilasas que transfieren dióxido de carbono en reacciones bioquímicas.", "Participa en el metabolismo de ácidos grasos, glucosa y aminoácidos.", "La deficiencia es rara, pero puede afectar la piel, el cabello y el sistema nervioso."], "hist": "La biotina fue reconocida como factor nutricional en estudios de crecimiento y metabolismo. La deficiencia puede darse en condiciones raras, como el déficit de biotinidasa.", "estudos": "La reposición es eficaz cuando hay deficiencia. No hay evidencia sólida de beneficio para el cabello y las uñas en personas sin deficiencia; las afirmaciones de los suplementos exceden los datos disponibles.", "evitar": "Dosis altas pueden interferir con pruebas de laboratorio, incluidas la troponina y las pruebas hormonales, produciendo resultados falsos. Informe al laboratorio y al profesional de salud antes de los análisis."}, "exenatida": {"oque": "Péptido sintético relacionado con la exendina-4, agonista del receptor de GLP-1. Se usa en algunas presentaciones para la diabetes tipo 2.", "age": ["Activa receptores de GLP-1 en el páncreas y en otros tejidos.", "Aumenta la secreción de insulina cuando la glucosa está elevada y reduce el glucagón.", "Retrasa el vaciamiento gástrico y puede reducir el apetito."], "hist": "La exenatida fue uno de los primeros agonistas de GLP-1 aprobados para la diabetes tipo 2. Existen presentaciones de acción corta y prolongada, con prospectos y disponibilidad que varían según el país.", "estudos": "Los ensayos clínicos demuestran mejoría de la glucemia y una pérdida de peso media modesta. Los beneficios y riesgos dependen de la presentación, de la condición clínica y de los medicamentos asociados.", "evitar": "Puede causar síntomas gastrointestinales e hipoglucemia en combinación con insulina o sulfonilureas. No está indicada en algunas enfermedades digestivas; consulte el prospecto y a un profesional."}, "lixisenatida": {"oque": "Péptido agonista del receptor de GLP-1 utilizado en algunos mercados para el tratamiento de la diabetes tipo 2.", "age": ["Activa el receptor de GLP-1 y aumenta la insulina de forma dependiente de la glucosa.", "Reduce el glucagón después de las comidas.", "Retrasa el vaciamiento gástrico, lo que contribuye al control de la glucemia posprandial."], "hist": "La lixisenatida es un agonista de GLP-1 de acción diaria estudiado y registrado en diferentes jurisdicciones. Las presentaciones combinadas y la disponibilidad varían según el país.", "estudos": "Los estudios demuestran mejoría glucémica en la diabetes tipo 2, con un efecto sobre el peso generalmente modesto. El beneficio cardiovascular no debe extrapolarse más allá de las poblaciones y los desenlaces estudiados.", "evitar": "Las náuseas y los vómitos son frecuentes al inicio. Puede haber hipoglucemia con otros antidiabéticos y alteración de la absorción de medicamentos orales; consulte el prospecto y el registro local."}, "dulaglutida": {"oque": "Proteína de fusión agonista del receptor de GLP-1, de acción prolongada, indicada para la diabetes tipo 2 en los mercados donde está registrada.", "age": ["Activa receptores de GLP-1 y aumenta la insulina cuando la glucosa está elevada.", "Reduce el glucagón y retrasa el vaciamiento gástrico.", "Puede disminuir el apetito y la ingesta de alimentos."], "hist": "La dulaglutida fue desarrollada para prolongar la acción del agonismo de GLP-1. Los ensayos cardiovasculares ampliaron el conocimiento sobre sus efectos en personas con diabetes tipo 2.", "estudos": "La eficacia glucémica y la reducción de peso están demostradas en ensayos. Un estudio cardiovascular mostró una reducción de eventos en una población con diabetes de alto riesgo; esto no significa prevención universal.", "evitar": "Puede causar náuseas, diarrea y problemas biliares. Se necesita evaluación ante dolor abdominal persistente, gastroparesia o uso concomitante de insulina."}, "maridebart-cafraglutida-maritide": {"oque": "Biológico experimental de acción prolongada, con actividad agonista de GLP-1R y antagonista de GIPR. No es un medicamento aprobado para uso general.", "age": ["Activa el receptor de GLP-1, una vía que participa en la saciedad y el control de la glucosa.", "Bloquea el receptor de GIP, pero el papel clínico de este antagonismo todavía se está investigando.", "La combinación busca influir en el apetito y el peso mediante vías incretínicas distintas."], "hist": "El compuesto, antes conocido como AMG 133, está en desarrollo clínico para la obesidad y otras condiciones metabólicas. La evidencia y la fase deben verificarse en registros de ensayos actualizados.", "estudos": "Los estudios iniciales observaron reducción de peso en los participantes, pero no establecen una comparación definitiva ni la seguridad a largo plazo. Se necesitan ensayos confirmatorios.", "evitar": "No está aprobado para comercialización ni automedicación. Se observaron efectos gastrointestinales y el perfil completo de seguridad, incluido el antagonismo de GIP, sigue en estudio."}, "petrelintida": {"oque": "Análogo de amilina de acción prolongada en investigación clínica para el control del peso. No está aprobado para comercialización.", "age": ["Imita parte de las acciones de la amilina, hormona cosecretada con la insulina.", "Actúa en vías relacionadas con la saciedad en el sistema nervioso.", "Puede retrasar el vaciamiento gástrico y reducir la ingesta de alimentos."], "hist": "La petrelintida fue desarrollada como un análogo de amilina con un perfil de acción prolongada. Su desarrollo y fase clínica deben seguirse en los registros y publicaciones actuales.", "estudos": "Los ensayos de fase 2 investigan el peso y la tolerabilidad. Los resultados iniciales no demuestran eficacia duradera ni seguridad de uso fuera de ensayos clínicos.", "evitar": "Es experimental y no debe obtenerse ni usarse fuera de una investigación autorizada. Son posibles las náuseas y otros efectos digestivos; las combinaciones con otros fármacos no están establecidas."}, "eloralintida": {"oque": "Péptido experimental agonista de receptores de amilina, investigado para enfermedades metabólicas y control del peso.", "age": ["Activa receptores relacionados con la señalización de la amilina.", "Puede aumentar la saciedad actuando en circuitos del sistema nervioso.", "La acción gástrica y metabólica todavía se está caracterizando en estudios."], "hist": "La eloralintida está en desarrollo clínico y no es un medicamento aprobado. El estado de la fase puede cambiar a medida que se registren nuevos ensayos.", "estudos": "Los estudios disponibles son iniciales y evalúan la seguridad y señales de eficacia. Aún no hay evidencia suficiente para determinar un beneficio clínico duradero.", "evitar": "No usar fuera de ensayos clínicos autorizados. La seguridad en el embarazo, en enfermedades coexistentes, en combinaciones y en el uso prolongado no está establecida."}, "orforglipron": {"oque": "Molécula pequeña oral agonista del receptor de GLP-1. No es un péptido, aunque actúa en el mismo receptor que los medicamentos peptídicos incretínicos.", "age": ["Se une al receptor de GLP-1 y lo activa.", "Aumenta la secreción de insulina cuando la glucosa está elevada y reduce las señales de glucagón.", "Puede retrasar el vaciamiento gástrico y disminuir el apetito."], "hist": "Desarrollado como agonista oral de GLP-1 no peptídico. La fase de desarrollo y la eventual situación regulatoria deben verificarse en fuentes oficiales actualizadas.", "estudos": "Los ensayos de fase 3 evalúan la glucemia, el peso y la seguridad. Los resultados de los ensayos no equivalen a una aprobación o indicación para uso individual.", "evitar": "Es experimental según la fase informada y no debe usarse fuera de estudios autorizados. Los posibles efectos gastrointestinales y los riesgos de clase exigen una evaluación regulatoria completa."}, "lanreotida": {"oque": "Análogo sintético de la somatostatina que reduce la secreción hormonal mediante la activación de receptores de somatostatina.", "age": ["Se une preferentemente a subtipos de receptores de somatostatina.", "Reduce la liberación de GH y, en consecuencia, puede reducir el IGF-1.", "También disminuye las secreciones gastrointestinales y las de algunos tumores neuroendocrinos."], "hist": "La lanreotida se usa desde hace décadas en la acromegalia y en los tumores neuroendocrinos, con formulaciones de depósito. Las indicaciones precisas varían según el país y la presentación.", "estudos": "Hay evidencia clínica del control bioquímico de la acromegalia y del control de algunos tumores neuroendocrinos. La respuesta depende del tumor, de la indicación y de la formulación.", "evitar": "Puede alterar la glucosa, el ritmo cardíaco y la vesícula biliar. La administración y el seguimiento deben ajustarse al prospecto y a un equipo especializado."}, "pasireotida": {"oque": "Análogo de somatostatina con afinidad por varios subtipos de receptores. Se usa en indicaciones hormonales seleccionadas.", "age": ["Activa receptores de somatostatina en la hipófisis y en otros tejidos.", "Puede reducir la ACTH y el cortisol en la enfermedad de Cushing.", "También puede reducir la secreción de GH e IGF-1 en la acromegalia."], "hist": "La pasireotida fue desarrollada para alcanzar un perfil más amplio de receptores de somatostatina que los análogos anteriores. Las formulaciones y las indicaciones difieren entre países.", "estudos": "Los ensayos respaldan su uso en pacientes seleccionados con enfermedad de Cushing y acromegalia. La hiperglucemia es un efecto adverso importante que puede limitar el tratamiento.", "evitar": "Requiere monitorización de la glucosa, de la vesícula biliar y, según el caso, del intervalo QT. No iniciar ni ajustar sin evaluación especializada y consulta del prospecto."}, "vasopressina": {"oque": "Hormona peptídica también llamada arginina-vasopresina, producida en el hipotálamo y liberada por la hipófisis posterior.", "age": ["Activa receptores V1a y contrae los vasos sanguíneos.", "Activa receptores V2 en los riñones y aumenta la reabsorción de agua.", "Su secreción está regulada por la osmolaridad de la sangre y por el volumen circulante."], "hist": "La vasopresina fue identificada como reguladora de la presión arterial y del balance hídrico. La forma farmacéutica tiene usos hospitalarios e indicaciones que varían entre jurisdicciones.", "estudos": "Existen usos clínicos establecidos en contextos específicos, como el soporte hemodinámico hospitalario. El uso y la evidencia no deben extrapolarse a fines no aprobados.", "evitar": "Puede causar isquemia, arritmia y retención de agua con descenso del sodio. La administración parenteral requiere monitorización clínica y de electrolitos."}, "terlipressina": {"oque": "Análogo sintético de la vasopresina y profármaco de la lisina-vasopresina, con acción vasoconstrictora predominantemente V1.", "age": ["Activa receptores vasculares V1 y reduce el flujo en territorios esplácnicos.", "Puede elevar el volumen arterial efectivo y la presión arterial media.", "En el síndrome hepatorrenal, puede mejorar la perfusión renal en pacientes seleccionados."], "hist": "La terlipresina se usa en varios países para condiciones distintas, pero las autorizaciones no son uniformes. La FDA aprobó Terlivaz para adultos con síndrome hepatorrenal tipo 1 con rápido deterioro de la función renal, y esa aprobación no abarca otras indicaciones.", "estudos": "Los ensayos demostraron mejoría de la función renal en pacientes seleccionados con síndrome hepatorrenal; el beneficio clínico depende de la población y no elimina riesgos graves.", "evitar": "Existe una alerta regulatoria de insuficiencia respiratoria grave o mortal e isquemia. El uso hospitalario exige una selección cuidadosa, evaluación respiratoria y confirmación del registro y de la indicación en el país."}, "degarelix": {"oque": "Antagonista peptídico del receptor de GnRH, usado en algunas jurisdicciones para el cáncer de próstata avanzado.", "age": ["Bloquea los receptores de GnRH en la hipófisis.", "Reduce la secreción de LH y FSH y la producción testicular de testosterona.", "A diferencia de los agonistas de GnRH, no suele provocar un aumento inicial de testosterona."], "hist": "El degarelix fue desarrollado como antagonista de GnRH de acción prolongada. Su aprobación y formulación dependen del mercado y de la indicación registrada.", "estudos": "Los ensayos clínicos respaldan la supresión rápida de testosterona en el cáncer de próstata hormonosensible. La elección depende del cuadro oncológico y de las alternativas disponibles.", "evitar": "Puede causar reacciones locales y alteraciones de la glucosa y del QT; la supresión hormonal también afecta a los huesos. Exige seguimiento oncológico."}, "cetrorrelix": {"oque": "Antagonista de GnRH usado en protocolos de reproducción asistida para evitar la liberación prematura de LH.", "age": ["Bloquea de forma reversible los receptores de GnRH en la hipófisis.", "Reduce la LH y la FSH durante el período de acción.", "Ayuda a evitar la ovulación espontánea antes del momento planificado en la fecundación asistida."], "hist": "El cetrorelix fue desarrollado para controlar el momento de la ovulación en tratamientos de reproducción asistida. El nombre solicitado, Cetrorrelix, corresponde al principio activo cetrorelix.", "estudos": "Hay evidencia de eficacia dentro de protocolos de fertilidad supervisados. No es un tratamiento aislado de la infertilidad y no debe extrapolarse a otros usos.", "evitar": "Puede haber reacciones locales o hipersensibilidad. El síndrome de hiperestimulación ovárica es un riesgo del protocolo de fertilidad y requiere seguimiento especializado."}, "triptorrelina": {"oque": "Agonista de GnRH que suprime las hormonas sexuales cuando se administra de forma continua en presentaciones apropiadas.", "age": ["Estimula inicialmente los receptores hipofisarios de GnRH y puede elevar la LH y la FSH.", "La exposición continua desensibiliza estos receptores.", "La producción de hormonas sexuales disminuye tras la fase inicial."], "hist": "La triptorelina se comercializa en presentaciones de depósito para indicaciones oncológicas y ginecológicas específicas. Las presentaciones no son intercambiables sin orientación.", "estudos": "La evidencia está establecida para indicaciones hormonosensibles específicas, y la eficacia depende de la enfermedad y de la formulación. La supresión hormonal tiene efectos sistémicos relevantes.", "evitar": "Pueden producirse empeoramiento inicial de los síntomas, pérdida ósea, alteraciones metabólicas y prolongación del QT. El uso exige indicación y seguimiento especializado."}, "goserelina": {"oque": "Agonista de GnRH administrado en formulaciones de depósito para suprimir las hormonas sexuales en indicaciones seleccionadas.", "age": ["Estimula inicialmente la hipófisis y puede causar una elevación transitoria de LH y FSH.", "Con la exposición continua, reduce la sensibilidad de los receptores hipofisarios.", "Disminuye la producción de estrógeno o testosterona, según el contexto fisiológico."], "hist": "La goserelina se utiliza en oncología y ginecología en implantes de depósito. La duración y las indicaciones autorizadas varían según la presentación y el país.", "estudos": "Los ensayos y el uso clínico respaldan indicaciones oncológicas y ginecológicas específicas. El beneficio debe sopesarse frente a los efectos de la supresión hormonal y ser seguido por un equipo clínico.", "evitar": "Puede causar sofocos, pérdida ósea, alteraciones metabólicas y reacción en el sitio de aplicación. El cáncer de próstata puede empeorar transitoriamente al inicio; requiere supervisión."}, "bivalirudina": {"oque": "Anticoagulante peptídico sintético relacionado con la hirudina. Inhibe directamente la trombina, enzima central en la formación de coágulos.", "age": ["Se une a la trombina y reduce su actividad enzimática.", "Disminuye la conversión de fibrinógeno en fibrina.", "También reduce la activación plaquetaria mediada por la trombina."], "hist": "Fue desarrollada como alternativa de acción directa a la heparina en contextos cardiovasculares. Su uso actual se define por la indicación y el protocolo hospitalario.", "estudos": "Existe evidencia clínica y aprobación para indicaciones cardiovasculares específicas. La elección en procedimientos depende del riesgo de sangrado, de la función renal y de las alternativas disponibles.", "evitar": "Puede causar sangrado grave y requiere evaluación de la función renal. No es un medicamento para usar sin supervisión hospitalaria."}, "ziconotida": {"oque": "Péptido sintético inspirado en la conotoxina de un caracol marino. Es un analgésico no opioide administrado directamente en el líquido que rodea la médula espinal.", "age": ["Bloquea canales de calcio neuronales de tipo N, llamados CaV2.2.", "Reduce la liberación de neurotransmisores ligados a la transmisión del dolor.", "La administración intratecal limita la exposición sistémica, pero no elimina los efectos neurológicos."], "hist": "La molécula se derivó de estudios de toxinas de Conus magus. La formulación intratecal fue aprobada por la FDA para el dolor crónico grave en pacientes seleccionados.", "estudos": "Los ensayos clínicos respaldan su uso en el dolor crónico grave, pero el margen entre beneficio y efectos adversos exige un ajuste cuidadoso y monitorización especializada.", "evitar": "Puede provocar confusión, alucinaciones y alteraciones cognitivas o psiquiátricas graves. Está contraindicada en personas con antecedentes de psicosis y no debe administrarse por vía sistémica."}, "linaclotida": {"oque": "Péptido oral que activa la guanilato ciclasa C en la superficie intestinal. Su absorción sistémica es mínima en las condiciones habituales.", "age": ["Activa el receptor guanilato ciclasa C en la mucosa intestinal.", "Aumenta el GMP cíclico local y la secreción de cloruro y bicarbonato.", "Eleva el contenido de agua de las heces y puede reducir el dolor visceral."], "hist": "Fue desarrollada para el estreñimiento y los síntomas del síndrome del intestino irritable con estreñimiento. Las indicaciones y los grupos de edad varían según el prospecto de cada país.", "estudos": "Los ensayos clínicos respaldan la eficacia en las indicaciones aprobadas. La diarrea es un evento adverso frecuente y puede llevar a la deshidratación.", "evitar": "No usar en menores de 2 años ni en obstrucción gastrointestinal conocida o sospechada. Busque evaluación si aparece diarrea intensa o signos de deshidratación."}, "icatibanto": {"oque": "Péptido sintético que bloquea el receptor B2 de la bradicinina. Se usa para tratar las crisis agudas de angioedema hereditario.", "age": ["Compite con la bradicinina por el receptor B2.", "Reduce los signos de dilatación vascular y aumento de permeabilidad asociados a la crisis.", "Se administra por vía subcutánea según el prospecto y la orientación clínica."], "hist": "Fue desarrollado para interferir en la vía de la bradicinina, importante en las crisis de angioedema hereditario. Hay formulaciones aprobadas en diferentes países, con registro local por confirmar.", "estudos": "Los ensayos clínicos respaldan el tratamiento de crisis agudas en las indicaciones aprobadas. La intensidad de la respuesta y el momento de la evaluación varían entre pacientes.", "evitar": "Las reacciones locales son frecuentes. La hinchazón de la lengua o la garganta, la dificultad para respirar o el empeoramiento rápido requieren atención de emergencia; el medicamento no sustituye el manejo de la vía aérea."}, "enfuvirtida": {"oque": "Péptido antirretroviral que impide la entrada del VIH-1 en células susceptibles. Se usa en combinación con otros antirretrovirales.", "age": ["Se une a la región HR1 de la proteína viral gp41.", "Impide los cambios estructurales necesarios para la fusión entre la envoltura del virus y la membrana celular.", "La combinación con otros antirretrovirales reduce la replicación y ayuda a limitar la resistencia."], "hist": "Fue uno de los primeros inhibidores de fusión del VIH-1 aprobados por la FDA. Su administración es subcutánea y puede causar reacciones locales repetidas.", "estudos": "Los ensayos y la experiencia clínica respaldan su uso en esquemas combinados, sobre todo en situaciones seleccionadas de tratamiento. La sensibilidad del virus y el historial terapéutico influyen en la respuesta.", "evitar": "No debe usarse de forma aislada. Las reacciones de hipersensibilidad, los nódulos y las infecciones en el sitio de aplicación requieren atención clínica."}, "difelikefalina": {"oque": "Péptido agonista selectivo de receptores opioides kappa con acción predominantemente periférica. La formulación aprobada se usa para el prurito asociado a la enfermedad renal crónica en adultos en hemodiálisis.", "age": ["Activa receptores kappa periféricos implicados en la señalización del picor.", "Modula señales sensoriales sin ser un agonista mu típico.", "Se administra por vía intravenosa durante la sesión de hemodiálisis, según el prospecto."], "hist": "La FDA aprobó la difelikefalina para el prurito de moderado a grave asociado a la enfermedad renal crónica en adultos sometidos a hemodiálisis. Esta indicación no debe extrapolarse a otras causas de picor.", "estudos": "Los ensayos clínicos en hemodiálisis demostraron una reducción del prurito en parte de los pacientes. Deben vigilarse la somnolencia, el mareo y las alteraciones del estado mental.", "evitar": "Los sedantes y otros depresores del sistema nervioso central pueden aumentar la somnolencia y el riesgo de caídas. No debe presumirse la seguridad en poblaciones fuera de la indicación aprobada."}, "cerebrolisina": {"oque": "Preparado complejo de péptidos y aminoácidos derivados de cerebro porcino, y no una molécula de secuencia única. Se comercializa y utiliza en algunos países para condiciones neurológicas.", "age": ["Contiene una mezcla de fragmentos peptídicos y aminoácidos.", "Se proponen efectos neurotróficos o neuroprotectores, pero no definen un mecanismo clínico comprobado.", "La mezcla no puede reducirse a un único receptor o diana molecular."], "hist": "Se usa en algunos países, mientras que no tiene aprobación de la FDA. La composición compleja dificulta comparar productos y atribuir efectos a componentes específicos.", "estudos": "Se ha investigado en estudios de ictus y otras enfermedades neurológicas, con resultados heterogéneos. Las revisiones y los ensayos no respaldan un beneficio definitivo en todas las indicaciones; el registro y la evidencia varían según el país.", "evitar": "No sustituye los tratamientos neurológicos establecidos ni la atención de emergencia. El origen biológico, la composición y los efectos adversos exigen cautela; verifique el registro en el organismo regulador local."}, "timalina": {"oque": "Preparado descrito como péptidos del timo y usado en Rusia como inmunomodulador. Su composición y su mecanismo clínico no están bien definidos.", "age": ["Se propone que los péptidos tímicos modulan la maduración de los linfocitos T.", "Se han sugerido efectos sobre otras células inmunes, pero no están bien caracterizados.", "La mezcla y la actividad pueden variar entre productos y fuentes."], "hist": "La timalina tiene un uso descrito en Rusia. El uso en un país no demuestra aprobación ni eficacia en los demás, y la evidencia disponible es limitada.", "estudos": "La etapa informada es preclínica en animales; la literatura es limitada y no hay una demostración sólida de beneficio clínico. No debe inferirse eficacia a partir del mecanismo propuesto.", "evitar": "La seguridad, la composición, las interacciones y los efectos en enfermedades autoinmunes no están bien establecidos. Verifique el registro local y no sustituya las terapias prescritas."}, "timopentina": {"oque": "Pentapéptido sintético derivado de una región de la timopoyetina, investigado por posibles efectos sobre la función de los linfocitos T. Su estado clínico actual varía según el país.", "age": ["Imita parte de una secuencia de la timopoyetina.", "Se ha estudiado como moduladora de la diferenciación y la actividad de los linfocitos T.", "Los efectos dependen del contexto y no equivalen a una estimulación inmune amplia comprobada."], "hist": "La timopentina fue evaluada en estudios clínicos, incluso en fases avanzadas, y usada en algunos países. La situación regulatoria actual debe verificarse para cada país e indicación.", "estudos": "El historial de ensayos, incluidos los estudios de fase 3, no basta para concluir una eficacia actual ni una aprobación amplia. La calidad y la relevancia de los datos varían según la indicación.", "evitar": "Los datos de seguridad a largo plazo y de interacciones son limitados. Se requiere cautela en enfermedades autoinmunes, trasplantes o uso de inmunosupresores, con evaluación profesional."}}};
